def device_label(handle, path, number=1):
    if handle == 0: return 'Precision Touchpad / System Input (Handle 0)'
    if handle == CURSOR: return 'System Cursor (Compatibility Test Only)'
    upper = path.upper()
    vendor = re.search(r'VID[_&]([0-9A-F]+)', upper)
    product = re.search(r'PID[_&]([0-9A-F]+)', upper)
    hardware = re.search(r'(ELAN[0-9A-F]+|SYNA[0-9A-F]+)', upper)
    if hardware:
        family = 'ELAN Input' if hardware[0].startswith('ELAN') else 'Synaptics Input'
        return f'{family} ({hardware[0]}) — Device {number}'
    if vendor or product:
        bus = 'Bluetooth HID' if '00001812-0000-1000-8000-00805F9B34FB' in upper else 'HID Mouse'
        return f'{bus} (VID {vendor[1] if vendor else "?"}, PID {product[1] if product else "?"}) — Device {number}'
    return f'Mouse Input — Device {number}'


def safe_component(value):
    value = re.sub(r'[<>:"/\\|?*\x00-\x1f]', '-', str(value)).strip(' .')
    if not value: value='Untitled'
    if value.split('.')[0].upper() in {'CON','PRN','AUX','NUL',*[f'COM{i}' for i in range(1,10)],*[f'LPT{i}' for i in range(1,10)]}:
        value='Recording-'+value
    return value[:100]


def output_context(mode, metadata, sequence, now=None):
    now=now or datetime.now()
    return dict(Date=now.strftime('%Y-%m-%d'),Time=now.strftime('%H-%M-%S'),Mode=mode,
                Animal=metadata.get('cricket_id') or 'Unspecified',Trial=metadata.get('trial_id') or 'Unspecified',
                Treatment=metadata.get('treatment') or 'Unspecified',Sequence=f'{sequence:04d}')


def render_name(pattern, values):
    for _,key,spec,conv in string.Formatter().parse(pattern):
        if key is not None and (key not in values or spec or conv):
            raise ValueError('Unknown name token: '+str(key)+'. Use the tokens listed below the fields.')
    return safe_component(pattern.format_map({k:safe_component(v) for k,v in values.items()}))


def output_plan(config, mode, metadata, sequence, now=None, reserve=False):
    root=Path(config['root']).expanduser()
    if not root.is_absolute(): raise ValueError('Please choose an absolute output folder path.')
    values=output_context(mode,metadata,sequence,now)
    folder=root
    if config['layout']=='Per Recording':
        name=render_name(config['folder_prefix']+config['folder_pattern']+config['folder_suffix'],values)
        folder=root/name
        if reserve:
            root.mkdir(parents=True,exist_ok=True)
            index=1
            while True:
                try: folder.mkdir(); break
                except FileExistsError:
                    index+=1; folder=root/(name+f'-{index:02d}')
    elif reserve: root.mkdir(parents=True,exist_ok=True)
    files={}
    for kind,ext in [('Raw','.csv'),('Samples','.csv'),('Metadata','.json'),('Events','.csv')]:
        name=render_name(config['file_prefix']+config['file_pattern']+config['file_suffix'],dict(values,Type=kind))
        files[kind.lower()]=folder/(name+ext)
    if len(set(files.values()))!=4: raise ValueError('File name template must distinguish all files; include {Type}.')
    if reserve:
        original=files.copy(); index=1
        while any(p.exists() for p in files.values()):
            index+=1; files={k:p.with_name(p.stem+f'-{index:02d}'+p.suffix) for k,p in original.items()}
    return folder,files

def resample(raw_path, out_path, duration, hz):
    """Streaming fixed bins; events on a right boundary enter the next bin."""
    with open(raw_path, newline='', encoding='utf-8') as src, open(out_path, 'w', newline='', encoding='utf-8') as dst:
        rows = iter(csv.DictReader(src)); row = next(rows, None)
        w = csv.writer(dst)
        w.writerow(['start_s','end_s','dt_s','dx','dy','x','y','vx','vy','speed','path_length','path_rate','packets'])
        x=y=0.0; start=0.0; k=1
        while start < duration:
            end = min(k/hz, duration); dx=dy=path=0.0; n=0
            while row is not None and float(row['time_s']) < end:
                dx += float(row['dx']); dy += float(row['dy']); path += math.hypot(float(row['dx']),float(row['dy'])); n+=1
                row=next(rows,None)
            dt=end-start; x+=dx; y+=dy
            w.writerow([start,end,dt,dx,dy,x,y,dx/dt,dy/dt,math.hypot(dx,dy)/dt,path,path/dt,n])
            start=end; k+=1

def resolve_input_device(selected, devices):
    """Rebind only an exact Windows device path; never guess from VID/PID or label."""
    if not selected:return None
    handle,path=selected
    if handle in (0,CURSOR):return selected
    if path and (path.startswith('\\') or path.startswith('HID#')):
        matches=[item for item in devices if item[1].casefold()==path.casefold()]
        return matches[0] if len(matches)==1 else None
    return next((item for item in devices if item[0]==handle),None)

class Engine:
    def __init__(self):
        self.lock=threading.RLock(); self.ready=threading.Event(); self.error=''; self.hwnd=None
        self.selected=None; self.recording_device=None; self.active=False; self.file=None; self.folder=None
        self.pending_capture=False
        self.x=self.y=self.distance=0.; self.packets=0; self.history=deque(maxlen=20000)
        self.motion_history=deque();self.trace=deque(maxlen=20000); self.events=[]; self.event_file=None
        self.recent=deque(); self.live={}; self.activity={}; self.last_device=None; self.absolute=0; self.duration=0.
        self.thread=threading.Thread(target=self.run,daemon=True); self.thread.start()
    def devices(self):
        if not hasattr(self,'u'): return []
        n=C.c_uint(); size=C.sizeof(self.DEVICE)
        if self.u.GetRawInputDeviceList(None,C.byref(n),size)==0xffffffff: raise C.WinError()
        arr=(self.DEVICE*n.value)()
        got=self.u.GetRawInputDeviceList(arr,C.byref(n),size)
        if got==0xffffffff: raise C.WinError()
        result=[]
        for d in arr[:got]:
            if d.kind != 0: continue
            length=C.c_uint()
            self.u.GetRawInputDeviceInfoW(d.handle,0x20000007,None,C.byref(length))
            buf=C.create_unicode_buffer(length.value+1)
            if self.u.GetRawInputDeviceInfoW(d.handle,0x20000007,buf,C.byref(length))==0xffffffff:buf.value='' 
            result.append((int(d.handle or 0),buf.value))
        return result
    def run(self):
        try:
            if sys.platform!='win32': raise RuntimeError('Windows is required for live Raw Input.')
            import win32gui, win32api
            from ctypes import wintypes as W
            self.gui=win32gui
            class HEADER(C.Structure):
                _fields_=[('kind',W.DWORD),('size',W.DWORD),('device',W.HANDLE),('param',C.c_size_t)]
            class MOUSE(C.Structure):
                _fields_=[('flags',W.USHORT),('buttons',W.ULONG),('rawbuttons',W.ULONG),('dx',W.LONG),('dy',W.LONG),('extra',W.ULONG)]
            class DEVICE(C.Structure):
                _fields_=[('handle',W.HANDLE),('kind',W.DWORD)]
            class RID(C.Structure):
                _fields_=[('page',W.USHORT),('usage',W.USHORT),('flags',W.DWORD),('target',W.HWND)]
            self.DEVICE=DEVICE;self.RID=RID; u=self.u=C.WinDLL('user32',use_last_error=True)
            u.GetRawInputDeviceList.argtypes=[C.c_void_p,C.POINTER(W.UINT),W.UINT]; u.GetRawInputDeviceList.restype=W.UINT
            u.GetRawInputDeviceInfoW.argtypes=[W.HANDLE,W.UINT,C.c_void_p,C.POINTER(W.UINT)]; u.GetRawInputDeviceInfoW.restype=W.UINT
            u.GetRawInputData.argtypes=[W.HANDLE,W.UINT,C.c_void_p,C.POINTER(W.UINT),W.UINT]; u.GetRawInputData.restype=W.UINT
            u.RegisterRawInputDevices.argtypes=[C.POINTER(RID),W.UINT,W.UINT]; u.RegisterRawInputDevices.restype=W.BOOL
            assert C.sizeof(MOUSE)==24 and MOUSE.dx.offset==12
            def proc(hwnd,msg,wp,lp):
                try:
                    if msg==0x00ff:
                        stamp=time.perf_counter(); size=W.UINT()
                        if u.GetRawInputData(lp,0x10000003,None,C.byref(size),C.sizeof(HEADER))==0xffffffff: raise C.WinError()
                        buf=C.create_string_buffer(size.value)
                        got=u.GetRawInputData(lp,0x10000003,buf,C.byref(size),C.sizeof(HEADER))
                        if got==0xffffffff: raise C.WinError()
                        if got>=C.sizeof(HEADER)+C.sizeof(MOUSE):
                            h=HEADER.from_buffer_copy(buf)
                            if h.kind==0:
                                m=MOUSE.from_buffer_copy(buf,C.sizeof(HEADER))
                                device=int(h.device or 0)
                                self.route_input(stamp,device,m.dx,m.dy,m.flags,m.buttons&0xffff,C.c_short(m.buttons>>16).value)
                    elif msg==0x0010:
                        win32gui.DestroyWindow(hwnd); return 0
                    elif msg==0x0002:
                        win32gui.PostQuitMessage(0); return 0
                except Exception:
                    self.error=traceback.format_exc()
                return win32gui.DefWindowProc(hwnd,msg,wp,lp)
            self.proc=proc
            wc=win32gui.WNDCLASS(); wc.lpfnWndProc=proc; wc.hInstance=win32api.GetModuleHandle(None); wc.lpszClassName='TreadmillRaw'+str(os.getpid())
            atom=win32gui.RegisterClass(wc)
            self.hwnd=win32gui.CreateWindowEx(0,atom,'Treadmill capture',0,0,0,0,0,0,0,wc.hInstance,None)
            rid=RID(1,2,0x100,self.hwnd)  # RIDEV_INPUTSINK; no cursor interception
            if not u.RegisterRawInputDevices(C.byref(rid),1,C.sizeof(RID)): raise C.WinError()
            self.ready.set(); win32gui.PumpMessages()
            win32gui.UnregisterClass(wc.lpszClassName,wc.hInstance)
        except Exception:
            self.error=traceback.format_exc(); self.ready.set()
    def route_input(self, stamp, device, rx, ry, flags=0, buttons=0, wheel=0):
        # Native Raw Input keeps the sensor identity separate from UI input.
        self.accept(stamp,device,rx,ry,flags)
    def accept(self, stamp, device, rx, ry, flags=0):
        with self.lock:
            self.last_device=device
            entry=self.activity.setdefault(device,dict(events=0,movement=0,last=0))
            entry['events']+=1; entry['movement']+=abs(rx)+abs(ry); entry['last']=stamp
            if flags & 1:
                if device==self.selected: self.absolute+=1
                return
            a,b=self.live.get(device,(0,0)); self.live[device]=(a+rx,b+ry)
            if not self.active or device!=self.recording_device or stamp<self.t0: return
            t=stamp-self.t0; p=self.params
            dx=rx*(-1 if p['invert_x'] else 1)/(p['cx'] if p['calibrated'] else 1)
            dy=ry*(-1 if p['invert_y'] else 1)/(p['cy'] if p['calibrated'] else 1)
            self.x+=dx; self.y+=dy; self.distance+=math.hypot(dx,dy); self.packets+=1
            self.writer.writerow([t,rx,ry,device,dx,dy,self.x,self.y,self.distance])
            if self.packets%100==0: self.file.flush()
            self.history.append((self.x,self.y)); self.trace.append((t,self.x,self.y,self.distance)); self.recent.append((stamp,dx,dy))
            self.motion_history.append((t,self.x,self.y,self.distance))
            while len(self.motion_history)>2 and self.motion_history[1][0]<t-70:self.motion_history.popleft()
            while self.recent and self.recent[0][0]<stamp-2: self.recent.popleft()
    def start(self, folder, params, metadata, device_path, files=None, mode='Trial'):
        with self.lock:
            if mode=='Trial' and self.selected in (None,0,CURSOR):
                raise ValueError('Select a physical Raw Input sensor. Merged system input cannot separate sensor and UI movement.')
            self.recording_device=self.selected
            self.post_stimulus_s=float(params.get('post_stimulus_s',0))
            if not math.isfinite(self.post_stimulus_s) or not 0<=self.post_stimulus_s<=86400:
                raise ValueError('Post-stimulus recording duration must be between 0 and 86400 seconds.')
            self.auto_stop_deadline=None;self.auto_stop_requested=False;self.first_stimulus_stamp=None
            self.params=params.copy(); self.folder=folder; self.error=''
            self.files=files or {k:folder/(k+ext) for k,ext in [('raw','.csv'),('samples','.csv'),('metadata','.json'),('events','.csv')]}
            self.unit='pixels' if self.selected==CURSOR else ('mm' if params['calibrated'] else 'counts')
            self.file=open(self.files['raw'],'x',newline='',encoding='utf-8'); self.writer=csv.writer(self.file)
            self.writer.writerow(['time_s','raw_dx','raw_dy','device_handle','dx','dy','x','y','path_length'])
            self.file.flush()
            self.event_file=open(self.files['events'],'x',newline='',encoding='utf-8')
            self.event_writer=csv.writer(self.event_file); self.event_writer.writerow(['time_s','event','source','device_time','clock','trial_id','detail']); self.event_file.flush()
            self.motion_history.clear();self.motion_history.append((0.,0.,0.,0.));self.events=[]; self.trace.clear(); self.trace.append((0.,0.,0.,0.))
            self.x=self.y=self.distance=0.; self.packets=0; self.absolute=0; self.history.clear(); self.history.append((0,0)); self.recent.clear()
            self.meta=dict(version=VERSION,trial=metadata.copy(),settings=params.copy(),device_path=device_path,device_handle=self.selected,
                           unit=self.unit,mode=mode,source='system_cursor' if self.selected==CURSOR else 'raw_input',files={k:str(v) for k,v in self.files.items()},utc_start=datetime.now(timezone.utc).isoformat(),
                           timestamp='perf_counter software receipt time',status='recording')
            self.meta['input_routing']=dict(sensor_handle=self.recording_device,sensor_path=device_path,acquisition_filter='recording_device handle',pointer_mode='native_windows',system_pointer_suppressed=False,acquisition_backend='raw_input')
            self.meta['event_timing']='Software receipt on perf_counter; device_time retained separately, not clock-mapped'
            self.write_meta(); self.t0=time.perf_counter(); self.duration=0.; self.active=True
    def mark_event(self, source='simulated', received_perf_counter=None, device_time=None):
        """Shared event sink. source=ttl is reserved for an actual acquisition adapter.
        received_perf_counter must be in THIS process's perf_counter clock.
        device_time is stored as uncalibrated metadata; never used for alignment.
        """
        with self.lock:
            if not self.active: return None
            if source not in ('simulated','ttl'):raise ValueError('Unknown stimulus source.')
            stamp=time.perf_counter() if received_perf_counter is None else float(received_perf_counter)
            t=stamp-self.t0
            if not math.isfinite(t) or t<0 or stamp>time.perf_counter():
                raise ValueError('Event timestamp must use this process perf_counter clock within the active recording.')
            item=dict(time_s=t,event='stimulus_onset',source=source,device_time=device_time,clock='software_receipt')
            self.event_writer.writerow([t,item['event'],source,'' if device_time is None else device_time,item['clock']]); self.event_file.flush()
            self.events.append(item); self.events.sort(key=lambda v:v['time_s'])
            self.arm_auto_stop(stamp)
            return item
    def hardware_event(self, event, stamp, trial='', device_time='', detail=''):
        with self.lock:
            if not self.active: return
            t = stamp - self.t0
            if t < 0: return
            item = dict(time_s=t, event=event, source='arduino', device_time=device_time,
                        clock='software_receipt' if event != 'command_sent' else 'software_send',
                        trial_id=trial, detail=detail)
            self.event_writer.writerow([item[k] for k in ('time_s','event','source','device_time','clock','trial_id','detail')])
            self.event_file.flush()
            self.events.append(item)
            self.events.sort(key=lambda v: v['time_s'])
            if event=='stimulus_onset':self.arm_auto_stop(stamp)

    def arm_auto_stop(self,stamp):
        # Called under the acquisition lock, only for confirmed onset markers.
        if self.first_stimulus_stamp is None:self.first_stimulus_stamp=stamp
        if self.post_stimulus_s>0 and self.auto_stop_deadline is None:
            self.auto_stop_deadline=stamp+self.post_stimulus_s
            self.meta['auto_stop']=dict(duration_s=self.post_stimulus_s,onset_s=stamp-self.t0,
                                       deadline_s=self.auto_stop_deadline-self.t0,basis='first stimulus onset; software receipt')

    def request_auto_stop(self,now=None):
        with self.lock:
            now=time.perf_counter() if now is None else now
            deadline=getattr(self,'auto_stop_deadline',None)
            if not self.active or deadline is None or self.auto_stop_requested or now<deadline:return False
            self.auto_stop_requested=True
            self.meta['auto_stop']['requested_s']=now-self.t0
            item=dict(time_s=now-self.t0,event='auto_stop_requested',source='software',device_time='',
                      clock='software_receipt',trial_id='',detail=f'First stimulus + {self.post_stimulus_s:g} s')
            self.event_writer.writerow([item[k] for k in ('time_s','event','source','device_time','clock','trial_id','detail')])
            self.event_file.flush();self.events.append(item)
            return True

    def record_ttl_edge(self, received_perf_counter=None, device_time=None):
        """Adapter hook only; no serial port or DAQ is opened by this program."""
        return self.mark_event('ttl',received_perf_counter,device_time)
    def write_meta(self):
        tmp=self.files['metadata'].with_suffix('.tmp'); tmp.write_text(json.dumps(self.meta,ensure_ascii=False,indent=2),encoding='utf-8'); tmp.replace(self.files['metadata'])
    def stop(self):
        with self.lock:
            self.duration=time.perf_counter()-self.t0; self.active=False
            self.file.flush(); os.fsync(self.file.fileno()); self.file.close(); self.file=None
            if self.event_file:
                self.event_file.flush(); os.fsync(self.event_file.fileno()); self.event_file.close(); self.event_file=None
            self.meta.update(events=self.events,duration_s=self.duration,packets=self.packets,ignored_absolute=self.absolute,status='raw_saved',error=self.error)
            self.write_meta()
        resample(self.files['raw'],self.files['samples'],self.duration,self.params['sample_hz'])
        self.meta['status']='complete' if not self.error else 'complete_with_error'; self.write_meta()
    def snapshot(self,window):
        with self.lock:
            now=time.perf_counter(); elapsed=now-self.t0 if self.active else self.duration
            recent=list(self.recent); points=list(self.history)
            dt=min(window,max(elapsed,1e-9))
            vx=sum(a for t,a,b in recent if t>=now-dt)/dt if self.active else 0
            vy=sum(b for t,a,b in recent if t>=now-dt)/dt if self.active else 0
            return dict(x=self.x,y=self.y,vx=vx,vy=vy,speed=math.hypot(vx,vy),distance=self.distance,
                        elapsed=elapsed,packets=self.packets,event_rate=sum(t>=now-1 for t,a,b in recent) if self.active else 0),points

# UI imports are below pure processing code, so --self-test needs no GUI packages.
def self_test():
    import tempfile
    with tempfile.TemporaryDirectory() as td:
        p=Path(td); raw=p/'raw.csv'
        with raw.open('w',newline='') as f:
            w=csv.writer(f); w.writerow(['time_s','dx','dy']); w.writerows([[.01,3,4],[.05,-3,-4],[.1,2,0]])
        resample(raw,p/'samples.csv',.25,10)
        rows=list(csv.DictReader((p/'samples.csv').open()))
        assert len(rows)==3 and float(rows[0]['speed'])==0 and float(rows[0]['path_length'])==10
        assert float(rows[1]['dx'])==2 and float(rows[2]['dx'])==0
        assert abs(float(rows[2]['dt_s'])-.05)<1e-9
    e=Engine.__new__(Engine); e.lock=threading.RLock(); e.last_device=None; e.live={}; e.activity={}; e.active=False; e.selected=7; e.recording_device=7; e.absolute=0
    e.accept(1,7,3,4); e.accept(2,8,9,9); e.accept(3,7,10,10,1)
    assert e.live[7]==(3,4) and e.absolute==1
    print('PASS: bin boundaries, zero motion, reversal, partial bin, device counters, absolute rejection')

if __name__=='__main__' and '--self-test' in sys.argv:
    self_test(); sys.exit()

