def numeric(value):
    if value == 0: return '0'
    if abs(value)>=1e6 or abs(value)<.001: return f'{value:.2e}'
    return f'{value:.6g}'


def nice_step(span):
    raw=max(span/8,1e-15); power=10**math.floor(math.log10(raw)); ratio=raw/power
    return next(v for v in [1,2,5,10] if v>=ratio)*power


class Plot(QWidget):
    viewChanged=pyqtSignal()
    def __init__(self):
        super().__init__(); self.points=[]; self.auto=True; self.radius=100.; self.cx=self.cy=0.; self.unit='counts'; self.drag=None
        self.setMinimumSize(420,280); self.setMouseTracking(True)
        self.setToolTip('Scroll to zoom around the pointer. Drag to pan. Both actions switch to Manual Scale.')
    def area(self):
        return QRectF(90,30,max(1,self.width()-120),max(1,self.height()-95))
    def geometry_values(self):
        rect=self.area(); scale=rect.width()/(2*self.radius); yr=rect.height()/(2*scale)
        return rect,scale,self.cx-self.radius,self.cx+self.radius,self.cy-yr,self.cy+yr
    def fit(self):
        pts=self.points or [(0,0)]
