        rect,scale,xlo,xhi,ylo,yhi=self.geometry_values()
        def at(x,y): return QPointF(rect.center().x()+(x-self.cx)*scale,rect.center().y()-(y-self.cy)*scale)
        step_x=nice_step(xhi-xlo); step_y=nice_step(yhi-ylo)
