        with self.engine.lock: self.engine.selected=item[0] if item else None
        self.last_cursor=None
        if item and item[0]==CURSOR:
            text='Compatibility Test: Touchpad and Mouse → Screen Pixels. All Pointer Sources Are Combined; Screen Edges Limit Movement.'
        elif item and item[0]==0:
            text='Precision Touchpad / System Input: Accepts Handle 0 Relative Events. Availability Depends on the Driver.'
        else: text='Recording: selected sensor only. Native Windows pointer: all pointing devices can move it; operator mouse movements are excluded from the recording.'
