        active=self.engine.active; cursor=self.engine.selected==CURSOR
        available=cursor or (not self.engine.error and self.engine.thread.is_alive())
        self.test_btn.setEnabled(not active and available and not self.detecting)
        self.start_btn.setEnabled(not active and available and self.engine.selected not in (None,0,CURSOR) and not self.detecting)
