        text.setPlainText(tr('Display Name')+': '+self.devices.itemText(self.devices.currentIndex())+'\n\n'+tr('Device Handle')+f': {item[0]}\n\n'+tr('Windows Device Path')+f':\n{item[1]}\n\n'+tr('Labels Based on Hardware IDs Are Descriptive Only. Use Detect Moving Device to Confirm the Source.'))
