from PyQt6.QtWidgets import QTabWidget,QSplitter,QGroupBox,QMenu,QButtonGroup,QGridLayout,QTableView,QAbstractItemView
from PyQt6.QtCore import QAbstractTableModel,QModelIndex


def basename_any(path): return str(path).replace('\\','/').rsplit('/',1)[-1]


class Recording:
    def __init__(self,rows=None,duration=0.,unit='counts',events=None,meta=None,name='Live Recording'):
        self.rows=rows or [(0.,0.,0.,0.)]; self.times=[r[0] for r in self.rows]
        self.duration=max(float(duration),self.times[-1]); self.unit=unit; self.events=[e for e in (events or []) if e.get('event','stimulus_onset') in ('stimulus_onset','stimulus_offset')]; self.meta=meta or {}; self.name=name
        self.warnings=[]; self.series={}; self.grid=[]; self.window=.1; self.display_step=.01
    def at(self,t):
        i=bisect.bisect_right(self.times,t)-1
        return self.rows[max(0,i)] if i>=0 else (0.,0.,0.,0.)
    def build_series(self,window=.1,hz=100,max_points=20000):
        self.window=max(.001,window); start=self.times[0]; span=max(0.,self.duration-start)
        self.display_step=max(1/max(1,hz),span/max_points)
        n=max(1,math.ceil(span/self.display_step)); self.grid=[start+i*self.display_step for i in range(n)]+[self.duration]
        self.series={k:[] for k in ('x','y','vx','vy','speed','distance','path_rate')}
        for t in self.grid:
            _,x,y,d=self.at(t); left=max(start,t-self.window); _,xx,yy,dd=self.at(left); dt=t-left
            vx=(x-xx)/dt if dt>1e-12 else 0.; vy=(y-yy)/dt if dt>1e-12 else 0.
            for key,val in [('x',x),('y',y),('vx',vx),('vy',vy),('speed',math.hypot(vx,vy)),('distance',d),('path_rate',(d-dd)/dt if dt>1e-12 else 0.)]:self.series[key].append(val)
        return self
    def metrics(self,start,end):
        start=max(0,min(start,self.duration)); end=max(start,min(end,self.duration)); a=self.at(start); b=self.at(end)
        speed=[v for t,v in zip(self.grid,self.series['speed']) if start<=t<=end]
        return dict(start_s=start,end_s=end,duration_s=end-start,net_x=b[1]-a[1],net_y=b[2]-a[2],
                    path_length=b[3]-a[3],mean_path_rate=(b[3]-a[3])/(end-start) if end>start else 0,
                    peak_windowed_speed=max(speed,default=0.),velocity_window_s=self.window,display_step_s=self.display_step,
                    events_in_interval=sum(start<=e['time_s']<=end for e in self.events),unit=self.unit)


def load_recording(path):
    path=Path(path); meta={}; warning=[]; meta_path=None
    if path.suffix.lower()=='.json':
        meta_path=path; meta=json.loads(path.read_text(encoding='utf-8-sig'))
        if not meta.get('files',{}).get('raw'):raise ValueError('This JSON does not identify a raw recording. Select the Raw CSV instead.')
        path=path.parent/basename_any(meta['files']['raw'])
    else:
        # Match exact raw basename; never attach an arbitrary neighbouring trial's metadata.
        matches=[]
        for candidate in path.parent.glob('*.json'):
            try:
                item=json.loads(candidate.read_text(encoding='utf-8-sig'))
                if isinstance(item,dict) and basename_any(item.get('files',{}).get('raw',''))==path.name: matches.append((candidate,item))
            except (OSError,ValueError):continue
        if len(matches)==1:meta_path,meta=matches[0]
        elif len(matches)>1:warning.append('Multiple matching metadata files; select the correct Metadata JSON to load units and events.')
        elif path.name.lower()=='raw.csv' and (path.parent/'metadata.json').exists():
            try:meta_path=path.parent/'metadata.json'; meta=json.loads(meta_path.read_text(encoding='utf-8-sig'))
            except (OSError,ValueError):meta={}
    preview_rows=[]
    rows=[(0.,0.,0.,0.)]; prev_time=0.; x=y=distance=0.; first=True
    with path.open(newline='',encoding='utf-8-sig') as f:
        reader=csv.DictReader(f); fields=reader.fieldnames or []
        if 'time_s' not in fields:raise ValueError('Expected Raw CSV with a time_s column; Samples CSV is not a raw recording.')
        cumulative=('x','y') if 'x' in fields and 'y' in fields else (('x_total','y_total') if 'x_total' in fields and 'y_total' in fields else None)
        delta=('dx','dy') if 'dx' in fields and 'dy' in fields else (('raw_dx','raw_dy') if 'raw_dx' in fields and 'raw_dy' in fields else None)
        if not cumulative and not delta:raise ValueError('No supported X/Y coordinates or displacement columns were found.')
        for line,row in enumerate(reader,2):
            if len(preview_rows)<10000:preview_rows.append([row.get(k,'') or '' for k in fields])
            try:
                t=float(row['time_s'])
                if cumulative:nx,ny=(float(row[k]) for k in cumulative)
                else:nx=x+float(row[delta[0]]);ny=y+float(row[delta[1]])
                if not all(math.isfinite(v) for v in [t,nx,ny]) or t<0 or t<prev_time:raise ValueError('Non-finite or decreasing time/coordinate')
                distance+=math.hypot(nx-x,ny-y); x,y=nx,ny; rows.append((t,x,y,distance)); prev_time=t
            except (TypeError,ValueError,KeyError) as ex:raise ValueError(f'Invalid raw data at line {line}: {ex}') from ex
    duration=max(prev_time,float(meta.get('duration_s',prev_time)))
    if not math.isfinite(duration):raise ValueError('Invalid recording duration.')
    events=[]
    event_name=meta.get('files',{}).get('events')
    event_path=path.parent/basename_any(event_name) if event_name else None
    if event_path and event_path.exists():
        with event_path.open(newline='',encoding='utf-8-sig') as f:
            for row in csv.DictReader(f):
                t=float(row['time_s'])
                if not math.isfinite(t) or t<0 or t>duration+1e-6:raise ValueError('Event timestamp lies outside the recording.')
                events.append({**row,'time_s':t})
    elif meta.get('events'):events=meta['events']
    events=sorted(events,key=lambda v:float(v['time_s']))
    for e in events:
        e['time_s']=float(e['time_s'])
        if not math.isfinite(e['time_s']) or not 0<=e['time_s']<=duration+1e-6:raise ValueError('Invalid event time in metadata.')
    unit=meta.get('unit','recorded units')
    if not meta:warning.append('No matching metadata: distance units and trailing idle duration are unknown. Stored coordinates are used without recalibration.')
    if meta.get('status') not in (None,'complete'):warning.append('Recording status: '+str(meta.get('status')))
    if not events:warning.append('No stimulus markers in this recording; all traces use the pre-stimulus colour.')
    result=Recording(rows,duration,unit,events,meta,path.name);result.source_path=path.resolve();result.metadata_path=meta_path.resolve() if meta_path else None; result.warnings=warning;result.csv_preview=(fields,preview_rows,len(rows)-1,str(path))
    return result.build_series(float(meta.get('settings',{}).get('window_ms',100))/1000,float(meta.get('settings',{}).get('sample_hz',100)))


