class PlotPanel(QFrame):
    def __init__(self,title,mode):
        super().__init__();layout=QVBoxLayout(self);layout.setContentsMargins(4,4,4,3);layout.setSpacing(2)
        header=QFrame();header.setObjectName('viewHeader');controls=QHBoxLayout(header);controls.setContentsMargins(7,1,6,1);controls.setSpacing(3)
        heading=QLabel(title);heading.setStyleSheet('font-weight:bold;color:#000000;');controls.addWidget(heading)
        self.selector=SelectBox();self.selector.addItems(PLOT_MODES);self.selector.setCurrentText(mode);self.selector.setMinimumWidth(130);self.selector.setMaximumWidth(210);self.selector.setSizePolicy(QSizePolicy.Policy.Preferred,QSizePolicy.Policy.Fixed);controls.addWidget(self.selector);controls.addStretch(1)
        self.overlay=QPushButton('Overlay');self.overlay.setFixedWidth(self.overlay.fontMetrics().horizontalAdvance('Overlay')+16);self.overlay.setToolTip('Choose traces and units for this time-series coordinate system.');controls.addWidget(self.overlay)
        self.fit_btn=QPushButton('Fit');self.fit_btn.setFixedWidth(self.fit_btn.fontMetrics().horizontalAdvance('Fit')+16);controls.addWidget(self.fit_btn)
        self.auto=QCheckBox('Auto');self.auto.setChecked(True);controls.addWidget(self.auto);layout.addWidget(header)
        self.legend=QLabel();self.legend.setWordWrap(True);self.legend.setStyleSheet('color:#555555;font-size:11px;');layout.addWidget(self.legend)
        self.canvas=ScientificCanvas();layout.addWidget(self.canvas,1)
        self.x_bar=QWidget();self.x_bar.setObjectName('zoomStrip');xrow=QHBoxLayout(self.x_bar);xrow.setContentsMargins(6,2,6,2);xrow.addWidget(QLabel('X Zoom'))
        self.x_zoom=QSlider(Qt.Orientation.Horizontal);self.x_zoom.setRange(-600,1200);self.x_zoom.setValue(0);xrow.addWidget(self.x_zoom,1)
        self.x_span=QLabel();self.x_span.setMinimumWidth(75);xrow.addWidget(self.x_span);layout.addWidget(self.x_bar)
        self.x_zoom.setToolTip('Logarithmic horizontal half-width. Vertical limits stay unchanged. Fit restores the complete record.')
        self.x_zoom.valueChanged.connect(self.zoom_x)
        self.selector.currentTextChanged.connect(self.change);self.auto.toggled.connect(self.auto_changed);self.fit_btn.clicked.connect(self.fit_view)
        self.canvas.manualChanged.connect(lambda:self.auto.setChecked(False));self.overlay.clicked.connect(self.customize)
        self.custom_keys=['x','y'];self.custom_normalized=False;self.change(mode)
    def change(self,mode):
        mode=self.selector.currentText()
        setting=mode=='Setting'
        if hasattr(self,'setting_widget'):
            self.setting_widget.setVisible(setting)
            for widget in (self.canvas,self.legend,self.overlay,self.fit_btn,self.auto):widget.setVisible(not setting)
        self.x_bar.setVisible(not setting and mode!='Trajectory')
        if setting or mode in ('Latency Review','Descriptive Statistics','Group Distribution','Airspeed–Response','Individual Summary','Latency ECDF'):return
        self.canvas.mode=mode;self.canvas.keys=self.custom_keys if mode=='Custom Overlay' else PLOT_MODES[mode];self.canvas.normalized=self.custom_normalized if mode=='Custom Overlay' else False
        self.overlay.setEnabled(mode not in ('Trajectory','Speed Distribution'));self.canvas.auto=self.auto.isChecked();self.canvas.fit();self.canvas.update()
        names=[TRACE_NAMES[k] for k in self.canvas.keys];styles=['solid','dash','dot','dash-dot','dash-dot-dot','solid']
        self.legend.setText(' · '.join(f'{name} ({styles[i]})' for i,name in enumerate(names)) if names and mode!='Speed Distribution' else ('Equal X/Y Scale · Right-Drag to Pan' if mode=='Trajectory' else 'Within-Phase Fractions · Equal-Time Samples'))
    def sync_x_zoom(self):
        a,b,_,_=self.canvas.bounds;radius=max(1e-6,min(1e12,(b-a)/2))
        self.x_zoom.blockSignals(True);self.x_zoom.setValue(round(math.log10(radius)*100));self.x_zoom.blockSignals(False)
        self.x_span.setText((f'{2*radius:.2f}' if .01<=2*radius<1e6 else numeric(2*radius))+(' '+self.canvas.record.unit+'/s' if self.canvas.mode=='Speed Distribution' else ' s'))
    def zoom_x(self,value):
        a,b,c,d=self.canvas.bounds;radius=10**(value/100);center=(a+b)/2
        self.auto.setChecked(False);self.canvas.bounds=(center-radius,center+radius,c,d);self.canvas.auto=False;self.canvas.update();self.sync_x_zoom()
    def auto_changed(self,on):self.canvas.auto=on;self.canvas.update()
    def fit_view(self):self.canvas.fit();self.canvas.update();self.sync_x_zoom()
    def customize(self):
        d=QDialog(self);d.setWindowTitle('Overlay Traces');d.resize(420,420);l=QVBoxLayout(d);checks={}
        l.addWidget(hint('Choose traces to draw together. Mixed distance and velocity require normalization to make their scales explicit.'))
        for k,name in TRACE_NAMES.items():
            checks[k]=QCheckBox(name);checks[k].setChecked(k in self.canvas.keys);l.addWidget(checks[k])
        normal=QCheckBox('Normalize Each Trace to 0–1');normal.setChecked(self.canvas.normalized);l.addWidget(normal)
        buttons=QDialogButtonBox(QDialogButtonBox.StandardButton.Ok|QDialogButtonBox.StandardButton.Cancel);l.addWidget(buttons);buttons.rejected.connect(d.reject)
        def accept():
            chosen=[k for k,v in checks.items() if v.isChecked()]
            if not chosen:QMessageBox.warning(d,'Choose a Trace','Select at least one trace.');return
            if len({k in ('vx','vy','speed','path_rate') for k in chosen})>1 and not normal.isChecked():QMessageBox.warning(d,'Different Units','Enable normalization to overlay distance and velocity.');return
            d.accept()
        buttons.accepted.connect(accept)
        if d.exec():self.custom_keys=[k for k,v in checks.items() if v.isChecked()];self.custom_normalized=normal.isChecked();self.selector.setCurrentText('Custom Overlay');self.change('Custom Overlay')


class StimulusTimeline(QWidget):
    seekTime=pyqtSignal(float)
    def __init__(self):
        super().__init__();self.setFixedHeight(62);self.setMouseTracking(True)
        self.record=None;self.playhead=0.;self.seek_enabled=False;self.dragging=False
        self.setToolTip('Stimulus timeline: S = simulated, T = TTL. Blue: before first stimulus; orange: after. In Replay, click or drag to seek.')
    def axis(self):return 78.,max(79.,self.width()-88.)
    def set_record(self,record,playhead):self.record=record;self.playhead=playhead;self.update()
    def time_at(self,pos):
        a,b=self.axis();return max(0,min(1,(pos.x()-a)/(b-a)))*(self.record.duration if self.record else 0)
    def mousePressEvent(self,event):
        if self.seek_enabled and event.button()==Qt.MouseButton.LeftButton:self.dragging=True;self.seekTime.emit(self.time_at(event.position()))
    def mouseMoveEvent(self,event):
        if self.dragging:self.seekTime.emit(self.time_at(event.position()))
        elif self.record:
            a,b=self.axis();duration=max(self.record.duration,1e-12)
            near=[(abs(a+e['time_s']/duration*(b-a)-event.position().x()),i,e) for i,e in enumerate(self.record.events,1)]
            if near and min(near,key=lambda v:v[0])[0]<8:
                _,i,e=min(near,key=lambda v:v[0]);self.setToolTip(f'{e.get("source","event")} #{i}: {e["time_s"]:.6f} s')
            else:self.setToolTip('Stimulus timeline: S = simulated, T = TTL. Blue: before first stimulus; orange: after. In Replay, click or drag to seek.')
    def mouseReleaseEvent(self,event):self.dragging=False
    def paintEvent(self,event):
        p=QPainter(self);p.setRenderHint(QPainter.RenderHint.Antialiasing);a,b=self.axis();y=20
        p.setPen(QColor('#595959'));p.drawText(QRectF(5,8,70,22),Qt.AlignmentFlag.AlignVCenter,'Stimulus')
        record=self.record;duration=(record.duration if record.duration>0 else 1) if record else 1;events=record.events if record else []
        onset=min((e['time_s'] for e in events if e.get('event')!='stimulus_offset'),default=duration);split=a+max(0,min(1,onset/duration))*(b-a)
        p.setPen(QPen(QColor(PRE),2));p.drawLine(QPointF(a,y),QPointF(split,y))
        p.setPen(QPen(QColor(POST if events else PRE),2));p.drawLine(QPointF(split,y),QPointF(b,y))
        last_label=[-100.,-100.];counts={}
        for e in events:
            if not 0<=e['time_s']<=duration:continue
            source=e.get('source','event');prefix={'simulated':'S','ttl':'T'}.get(source,'E');counts[prefix]=counts.get(prefix,0)+1
            x=a+e['time_s']/duration*(b-a);label=(('OFF' if e.get('event')=='stimulus_offset' else 'ON')+str(e.get('trial_id',''))) if source=='arduino' else f'{prefix}{counts[prefix]}'
            p.setPen(QPen(QColor('#6c6c6c'),1));p.drawLine(QPointF(x,y-5),QPointF(x,y+5))
            lane=0 if x-last_label[0]>35 else 1
            if x-last_label[lane]>35:
                p.drawText(QRectF(max(a,min(b-30,x-15)),0 if lane==0 else 24,34,16),Qt.AlignmentFlag.AlignCenter,label);last_label[lane]=x
        step=nice_step(duration);p.setPen(QPen(QColor('#777777'),.8))
        for i in range(int(duration/step)+1):
            t=i*step;x=a+t/duration*(b-a);p.drawLine(QPointF(x,y+6),QPointF(x,y+10))
            p.drawText(QRectF(x-30,43,60,16),Qt.AlignmentFlag.AlignCenter,numeric(t))
        p.drawText(QRectF(b+27,43,60,16),Qt.AlignmentFlag.AlignLeft,'Time (s)')
        head=a+max(0,min(1,self.playhead/duration))*(b-a)
        p.setPen(QPen(QColor('#2c2c2c'),1));p.drawLine(QPointF(head,y-8),QPointF(head,y+8))
        p.setPen(QColor('#595959'));p.drawText(QRectF(b+7,8,80,22),Qt.AlignmentFlag.AlignVCenter,f'{record.duration:.2f} s' if record else '0.00 s')


