def move_recording_to_delete(record,root,folder='Delete'):
    raw=record.source_path.resolve();meta_path=record.metadata_path
    paths={raw}
    if meta_path:
        meta_path=meta_path.resolve();paths.add(meta_path)
        # Read the current manifest so failure cannot move an unrelated replacement.
        meta=json.loads(meta_path.read_text(encoding='utf-8-sig'))
        if basename_any(meta.get('files',{}).get('raw',''))!=raw.name:
            raise ValueError('Recording metadata changed; reopen the recording before deleting.')
        for kind in ('samples','events'):
            value=meta.get('files',{}).get(kind)
            if value:
                companion=raw.parent/basename_any(value)
                if companion.exists():paths.add(companion.resolve())
        for candidate in raw.parent.glob('*.json'):
            if candidate.resolve()==meta_path:continue
            try:other=json.loads(candidate.read_text(encoding='utf-8-sig'))
            except (OSError,ValueError):continue
            if isinstance(other,dict):
                shared={raw.parent/basename_any(v) for v in other.get('files',{}).values() if isinstance(v,str)}
                if paths.intersection(p.resolve() for p in shared):
                    raise ValueError('Another recording references these files. Resolve the shared metadata before deleting.')
    if any(not p.is_file() for p in paths):raise FileNotFoundError('Recording files changed; reopen the recording.')
    root=Path(root).expanduser().resolve()
    if not raw.is_relative_to(root):root=raw.parent
    destination=root/folder/(raw.stem+'-'+uuid.uuid4().hex[:8])
    destination.mkdir(parents=True,exist_ok=False);moved=[]
    try:
        for source in sorted(paths):
            target=destination/source.name
            if target.exists():raise FileExistsError(str(target))
            shutil.move(str(source),str(target));moved.append((source,target))
    except Exception as ex:
        failures=[]
        for source,target in reversed(moved):
            try:shutil.move(str(target),str(source))
            except OSError as rollback:failures.append(str(rollback))
        if not failures:destination.rmdir()
        raise RuntimeError(str(ex)+(f' Partial move: inspect {destination}. '+ '; '.join(failures) if failures else ' Files restored.')) from ex
    return destination,paths


class RecordingNavigator(QLabel):
    stepped=pyqtSignal(int)
    def __init__(self,text):
        super().__init__(text);self.wheel_remainder=0
        self.setStyleSheet('background: #fafafa; border: 1px solid #d2d2d2; border-radius: 4px; padding: 3px 8px;')
        self.setToolTip('Scroll up: previous trial · Scroll down: next trial')
    def wheelEvent(self,event):
        self.wheel_remainder+=event.angleDelta().y()
        steps=int(self.wheel_remainder/120)
        if steps:
            self.wheel_remainder-=steps*120;self.stepped.emit(-steps)
        event.accept()
    def leaveEvent(self,event):
        self.wheel_remainder=0;super().leaveEvent(event)


