def rate_segments(rows, window, end, start=None):
    """Exact trailing path-rate steps: (t-window,t], not net displacement.
    Full window required. Evaluates packet entries and expirations, no grid resampling.
    """
    if not rows:return []
    times=[r[0] for r in rows];dist=[r[3] for r in rows]
    begin=max(times[0]+window,window if start is None else start)
    if end<begin:return []
    knots={begin,end}
    for t in times:
        if begin<t<end:knots.add(t)
        if begin<t+window<end:knots.add(t+window)
    def distance(t):return dist[max(0,bisect.bisect_right(times,t+1e-12)-1)]
    return [(t,max(0.,distance(t)-distance(t-window))/window) for t in sorted(knots)]


def movement_runs(segments, threshold, end):
    runs=[];beg=None
    for t,v in segments:
        if v>threshold and beg is None:beg=t
        elif v<=threshold and beg is not None:runs.append((beg,t));beg=None
    if beg is not None:runs.append((beg,end))
    return runs


def stimulus_sources(params):
    return ('arduino','ttl','simulated') if params.get('include_simulated',False) else ('arduino','ttl')

def detect_latencies(record, params):
    w=params['window_ms']/1000;confirm=params['confirmation_ms']/1000
    baseline=params['baseline_ms']/1000;search=params['response_ms']/1000
    delay=params['airflow_ms'];threshold=params['threshold']
    segments=rate_segments(record.rows,w,record.duration)
    runs=movement_runs(segments,threshold,record.duration)
    ends=[v[1] for v in runs]
    onsets=[e for e in record.events if e.get('event','stimulus_onset')=='stimulus_onset' and e.get('source') in stimulus_sources(params)]
    results=[]
    for i,event in enumerate(onsets):
        t=event['time_s'];next_t=onsets[i+1]['time_s'] if i+1<len(onsets) else math.inf
        limit=min(t+search,record.duration,next_t)
        result=dict(stimulus_id=event.get('trial_id') or i+1,on_s=t,movement_s='',raw_latency_ms='',
                    airflow_delay_ms=delay,corrected_latency_ms='',status='',quality='',source=event.get('source'),
                    time_basis=event.get('clock','software_receipt'),unit=record.unit,recording=record.name,
                    threshold=threshold,window_ms=params['window_ms'],confirmation_ms=params['confirmation_ms'],
                    baseline_ms=params['baseline_ms'],response_ms=params['response_ms'],software_version=VERSION)
        left=t-baseline
        if left<w or not segments:result['status']='Insufficient baseline'
        else:
            first=bisect.bisect_right(ends,left)
            relevant=runs[first:]
            if relevant and relevant[0][0]<t and relevant[0][1]>left:
                result['status']='Already moving'
            else:
                for a,b in relevant:
                    if a>=limit:break
                    if a<t:continue
                    if min(b,limit)-a+1e-12>=confirm:
                        raw=(a-t)*1000;corrected=raw-delay
                        result.update(movement_s=a,raw_latency_ms=raw,corrected_latency_ms=corrected,status='Response',
                                      quality='Negative corrected latency' if corrected<0 else 'Uncalibrated PC/device alignment')
                        break
                if not result['status']:
                    result['status']='No response' if limit>=t+search-1e-12 else 'Interrupted by next stimulus' if next_t<=record.duration else 'Insufficient recording'
        results.append(result)
    return results


class LatencyWorker(QThread):
    completed=pyqtSignal(object);failed=pyqtSignal(str)
    def __init__(self,record,params):super().__init__();self.record=record;self.params=params
    def run(self):
        try:self.completed.emit(detect_latencies(self.record,self.params))
        except Exception as ex:self.failed.emit(str(ex))

class StimulusLink:
    """One serial owner; timestamps and event writes happen in the reader thread."""
    def __init__(self, engine):
        self.engine=engine; self.commands=queue.Queue(); self.notice=queue.Queue()
        self.ready=False; self.pending=False; self.thread=None; self.quit=threading.Event()
        self.next_id=0; self.port=''; self.error=''; self.last_reply=0;self.reply_deadline=0
    def connect(self, port, baud):
        self.port=port; self.baud=baud; self.quit.clear(); self.error=''
        self.thread=threading.Thread(target=self.run, daemon=True); self.thread.start()
    def log(self, event, trial='', device='', detail='', stamp=None):
        self.engine.hardware_event(event, time.perf_counter() if stamp is None else stamp, trial, device, detail)
    def pulse(self, duration):
        if not self.ready or self.pending: return
        self.next_id+=1; self.pending=True
        self.commands.put(f'PULSE,{self.next_id},{duration}')
    def stop(self):
        # Cancel commands that have not yet reached the serial owner.
        while True:
            try:self.commands.get_nowait()
            except queue.Empty:break
        self.commands.put('STOP')
    def run(self):
        try:
            with serial.Serial(self.port, self.baud, timeout=.02, write_timeout=.1) as ser:
                buf=b''; last_ping=0; opened=time.perf_counter(); self.last_reply=opened
                while not self.quit.is_set():
                    now=time.perf_counter()
                    if now-last_ping>.1:
                        ser.write(b'PING\n');last_ping=now
                    if self.ready:
                        try:cmd=self.commands.get_nowait()
                        except queue.Empty:cmd=None
                        if cmd:
                            sent=time.perf_counter();ser.write((cmd+'\n').encode('ascii'))
                            if cmd.startswith('PULSE,'):self.reply_deadline=sent+int(cmd.split(',')[2])/1000+1.5
                            self.log('command_sent',cmd.split(',')[1] if cmd.startswith('PULSE,') else '',detail=cmd,stamp=sent)
                    data=ser.read(ser.in_waiting or 1)
                    buf+=data
                    if len(buf)>4096:raise RuntimeError('Serial input overflow')
                    while b'\n' in buf:
                        line,buf=buf.split(b'\n',1);stamp=time.perf_counter()
                        text=line.decode('ascii',errors='replace').strip();parts=text.split(',')
                        if text in ('READY,1','PONG,1'):
                            self.ready=True; self.last_reply=stamp
                            if text=='READY,1':
                                self.pending=False;self.log('device_reset',detail=text,stamp=stamp)
                        elif len(parts)>=3 and parts[0] in ('ON','OFF'):
                            int(parts[1]);int(parts[2]);self.last_reply=stamp
                            self.log('stimulus_onset' if parts[0]=='ON' else 'stimulus_offset',parts[1],parts[2],','.join(parts[3:]),stamp)
                            if parts[0]=='OFF':self.pending=False
                            self.notice.put(text)
                        elif text=='STOPPED':
                            self.pending=False;self.notice.put(text)
                        elif parts[0] in ('BUSY','ERROR'):
                            self.log('device_error',detail=text,stamp=stamp);self.pending=False;self.notice.put(text)
                    if self.pending and self.reply_deadline and now>self.reply_deadline:raise RuntimeError('Missing pulse acknowledgement; reconnect required')
                    if now-opened>5 and now-self.last_reply>2:raise RuntimeError('Arduino handshake/heartbeat timeout')
                ser.write(b'STOP\n')
        except Exception as ex:
            self.error=str(ex)
            try:self.log('connection_lost',detail=self.error)
            except Exception:pass
            self.notice.put('Connection error: '+self.error)
        finally:self.ready=False;self.pending=False

