        if answer!=QMessageBox.StandardButton.Yes:return
        self.pause()
        try:destination,paths=move_recording_to_delete(record,self.output['root'])
        except Exception as ex:QMessageBox.warning(self,'Recording Could Not Be Moved',str(ex));return
        if self.engine.folder and Path(self.engine.files['raw']).resolve() in paths:self.engine.folder=None
        self.replay_record=None;self.analysis_record=None;self.summary=None;self.latency_results=[];self.replay_time=0
        empty=Recording().build_series()
