        PLOT_COLORS.update(self.plot_colors);PRE=PLOT_COLORS['before'];POST=PLOT_COLORS['after']
        UI_LANGUAGE='en'
        self.refresh_shortcut_labels();localize(self)
        for board in (self.capture_board,self.replay_board,self.analysis_board):
            for panel in board.panels:panel.canvas._path_signature=None;panel.canvas.update()
