    def refresh_shortcut_labels(self):
        for action,button in [('quick',self.test_btn),('start',self.start_btn),('stop',self.stop_btn),('stimulus',self.stimulus),('open',self.open_btn)]:
            button.setText(tr(KEY_NAMES[action])+' ('+QKeySequence(self.keybindings[action]).toString()+')')
            button._i18n_text=(KEY_NAMES[action]+' ('+QKeySequence(self.keybindings[action]).toString()+')',button.text())
        self.settings_button.setText('Settings')
        width=max(button.fontMetrics().horizontalAdvance(button.text()) for button in (self.stimulus,self.start_btn,self.stop_btn))+24
        width=round(width*1.35)
        for button in (self.stimulus,self.start_btn,self.stop_btn):button.setFixedWidth(width)
        playkey=self.keybindings['play'];label='Pause' if self.playing else 'Play'
        self.play_btn.setText(tr(label)+' ('+('Space / '+playkey if playkey!='Space' else 'Space')+')')
        self.play_btn._i18n_text=(label+' ('+('Space / '+playkey if playkey!='Space' else 'Space')+')',self.play_btn.text())
