# Project recordings: immutable raw sources, SQLite labels/index and parameter-specific analyses.
import zipfile, tempfile, hashlib, statistics

ANALYSIS_VERSION = 'latency-pathrate-1;post-onset-1;stimulus-selection-2'
STAT_MODES = ('Descriptive Statistics','Group Distribution','Airspeed–Response','Individual Summary','Latency ECDF')
METRIC_FIELDS = {'Corrected Latency':'corrected_latency_ms','Raw Latency':'raw_latency_ms',
                 'Peak Speed':'peak_speed','Displacement':'displacement','Path Length':'post_path_length'}


def atomic_json(path,data):
    path=Path(path);path.parent.mkdir(parents=True,exist_ok=True)
    tmp=path.with_name(path.name+'.'+uuid.uuid4().hex+'.tmp')
    try:
        with tmp.open('w',encoding='utf-8') as f:
            json.dump(data,f,ensure_ascii=False,indent=2);f.flush();os.fsync(f.fileno())
        os.replace(tmp,path)
    finally:tmp.unlink(missing_ok=True)


def valid_project(name):
    name=str(name).strip()
    if not name or safe_component(name)!=name or name.casefold() in {'delete','test delete','summary'} or name.startswith('.'):
        raise ValueError('Enter a project name suitable for a Windows folder (no / \\ : * ? " < > |).')
    return name


def recording_metadata(path):
    path=Path(path)
    if path.suffix.lower()=='.zip':
        with zipfile.ZipFile(path) as z:
            info=z.getinfo('metadata.json')
            if info.file_size>16*1024*1024:raise ValueError('Metadata is too large.')
            return json.loads(z.read(info).decode('utf-8-sig'))
    return json.loads(path.read_text(encoding='utf-8-sig'))


def next_project_trial(root):
    root=Path(root);largest=0
    state=root/'.project.json'
    if state.exists():
        try:largest=max(0,int(json.loads(state.read_text(encoding='utf-8-sig')).get('last_trial',0)))
        except (ValueError,TypeError):raise ValueError('Project counter is invalid: '+str(state))
    # Include Delete and recoverable unfinished recordings; never recycle their IDs.
    if root.exists():
        for p in root.rglob('*'):
            if p.suffix.lower() not in ('.zip','.json') or p.name.startswith('.'):continue
            try:
                meta=recording_metadata(p);value=str(meta.get('trial',{}).get('trial_id',''))
                if value.isdigit():largest=max(largest,int(value))
            except (OSError,ValueError,KeyError,zipfile.BadZipFile):continue
    return f'{largest+1:04d}'


def trial_prefix(metadata):
    animal=str(metadata.get('cricket_id','')).strip()
    if not animal:raise ValueError('Enter an Animal ID before generating a Trial ID.')
    try:speed=float(str(metadata.get('air_speed_m_s','')).strip())
    except (ValueError,TypeError):raise ValueError('Enter an air speed in m/s before generating a Trial ID.')
    if not math.isfinite(speed) or speed<0:raise ValueError('Air speed must be finite and nonnegative.')
    speed=0. if speed==0 else speed
    return safe_component(animal)+'-'+format(speed,'.12g')


def next_condition_sequence(root,metadata):
    """Per Animal/Airspeed IDs, including trash and unfinished captures."""
    root=Path(root);prefix=trial_prefix(metadata);largest=0
    state=root/'.project.json'
    if state.exists():
        data=json.loads(state.read_text(encoding='utf-8-sig'))
        largest=max(0,int(data.get('trial_sequences',{}).get(prefix.casefold(),0)))
    if root.exists():
        for p in root.rglob('*'):
            if p.suffix.lower() not in ('.zip','.json') or p.name.startswith('.'):continue
            try:
                value=str(recording_metadata(p).get('trial',{}).get('trial_id',''))
                stem,sep,tail=value.rpartition('-')
                if sep and stem.casefold()==prefix.casefold() and tail.isdigit():largest=max(largest,int(tail))
            except (OSError,ValueError,KeyError,zipfile.BadZipFile):continue
    if (root/DB_NAME).exists():
        with ProjectStore(root) as store:largest=max(largest,store.next_sequence(metadata.get('cricket_id',''),metadata.get('air_speed_m_s',''))-1)
    return largest+1


def stream_digest(stream):
    h=hashlib.sha256()
    for block in iter(lambda:stream.read(1024*1024),b''):h.update(block)
    return h.digest()

legacy_output_plan=output_plan

def output_plan(config,mode,metadata,sequence,now=None,reserve=False):
    project=valid_project(metadata.get('project',''))
    root=Path(config['root']).expanduser()
    if not root.is_absolute():raise ValueError('Choose an absolute output folder.')
    root=root/project
    values=output_context(mode,metadata,sequence,now)
    folder=root
    if config['layout']=='Per Recording':
        folder=root/render_name(config['folder_prefix']+config['folder_pattern']+config['folder_suffix'],values)
    name=safe_component(str(metadata.get('trial_id','')).strip())
    if not name:raise ValueError('Enter a Trial ID before saving.')
    archive=folder/(name+'.zip');idx=1
    while archive.exists():
        idx+=1;archive=folder/(name+f'-{idx:02d}.zip')
    work=folder/('.inprogress-'+(uuid.uuid4().hex if reserve else 'recording'))
    if reserve:
        root.mkdir(parents=True,exist_ok=True)
        lock=root/'.trial-allocation.lock'
        try:fd=os.open(lock,os.O_CREAT|os.O_EXCL|os.O_WRONLY)
        except FileExistsError:raise ValueError('Another recording is allocating a trial. If a previous process crashed, remove '+str(lock))
        try:
            os.close(fd)
            trial=str(metadata.get('trial_id',''))
            state=root/'.project.json'
            data=json.loads(state.read_text(encoding='utf-8-sig')) if state.exists() else {'project':project,'last_trial':0}
            if metadata.get('auto_trial_id'):
                prefix=trial_prefix(metadata);stem,sep,tail=trial.rpartition('-')
                if not sep or stem!=prefix or not tail.isdigit() or int(tail)<next_condition_sequence(root,metadata):
                    raise ValueError('Trial sequence changed. Click Save Setting again before recording.')
                data.setdefault('trial_sequences',{})[prefix.casefold()]=int(tail)
                atomic_json(state,data)
            elif trial.isdigit():
                data['last_trial']=max(int(data.get('last_trial',0)),int(trial));atomic_json(state,data)
            work.mkdir(parents=True,exist_ok=False)
        finally:lock.unlink(missing_ok=True)
    return folder,{'raw':work/'raw.csv','events':work/'events.csv','metadata':work/'metadata.json','archive':archive}


LegacyEngine=Engine

def pending_lease(work):
    """Prevent another app instance from recovering a live/owned capture."""
    f=(Path(work)/'.session-lock').open('a+b')
    try:
        if sys.platform=='win32':
            import msvcrt
            if f.seek(0,2)==0:f.write(b'0');f.flush()
            f.seek(0);msvcrt.locking(f.fileno(),msvcrt.LK_NBLCK,1)
        else:
            import fcntl
            fcntl.flock(f.fileno(),fcntl.LOCK_EX|fcntl.LOCK_NB)
        return f
    except OSError:f.close();return None


class Engine(LegacyEngine):
    def start_pending(self,params,device_path,draft,output,sequence):
        if self.active or self.pending_capture:raise ValueError('Save or delete the pending recording first.')
        work=CONFIG.parent/'pending-recordings'/uuid.uuid4().hex
        work.mkdir(parents=True,exist_ok=False)
        self.pending_lease=pending_lease(work)
        if self.pending_lease is None:raise ValueError('Pending recording is in use by another app instance.')
        self.folder=work;self.pending_capture=True
        files={k:work/name for k,name in (('raw','raw.csv'),('events','events.csv'),('metadata','metadata.json'))}
        try:
            self.start(work,params,{},device_path,files=files,mode='Trial')
            self.meta.update(pending_capture=True,draft_trial=draft.copy(),pending_output=output.copy(),pending_sequence=sequence)
            self.write_meta()
        except Exception:
            self.active=False
            for attr in ('file','event_file'):
                f=getattr(self,attr,None)
                if f:f.close();setattr(self,attr,None)
            if not any(p.name!='.session-lock' for p in work.iterdir()):
                self.pending_lease.close();self.pending_lease=None;shutil.rmtree(work);self.pending_capture=False;self.folder=None
            raise

    def pending_directory(self):
        work=Path(self.folder).resolve()
        if not self.pending_capture or work.parent!=(CONFIG.parent/'pending-recordings').resolve() or not re.fullmatch(r'[0-9a-f]{32}',work.name):
            raise ValueError('This operation is limited to the current unsaved capture.')
        return work

    def save_pending(self,config,metadata,sequence):
        if self.active:raise ValueError('Stop recording before saving.')
        work=self.pending_directory()
        for attr in ('file','event_file'):
            f=getattr(self,attr,None)
            if f:f.flush();os.fsync(f.fileno());f.close();setattr(self,attr,None)
        if not all((work/name).is_file() for name in ('raw.csv','events.csv','metadata.json')):
            raise ValueError('Pending capture is incomplete. Its files have been retained.')
        # Use the original capture time for filename tokens, and final labels for Trial.
        now=datetime.fromisoformat(self.meta['utc_start']).astimezone()
        project=valid_project(metadata.get('project',''))
        root=Path(config['root']).expanduser()/project
        root.mkdir(parents=True,exist_ok=True);lock=root/'.trial-allocation.lock'
        try:fd=os.open(lock,os.O_CREAT|os.O_EXCL|os.O_WRONLY)
        except FileExistsError:raise ValueError('Another recording is being saved. Try Save again when it finishes.')
        tmp=None
        try:
            os.close(fd);trial=metadata.copy()
            inferred=group_from_animal(trial.get('cricket_id',''))
            if inferred:trial['treatment']=inferred
            with ProjectStore(root) as store:store.sync()
            if trial.get('auto_trial_id'):
                trial['trial_id']=f'{trial_prefix(trial)}-{next_condition_sequence(root,trial):03d}'
            else:
                seq=trial_sequence(trial.get('trial_id',''))
                if seq is None or str(trial.get('trial_id','')).rsplit('-',1)[0]!=trial_prefix(trial):
                    raise ValueError('Manual Trial ID must use Animal-Airspeed-Sequence, e.g. C2.8-30-006.')
            with ProjectStore(root) as store:
                if any(str(r['trial_id']).casefold()==str(trial['trial_id']).casefold() for r in store.catalog()):
                    raise ValueError('Trial ID already exists, including deleted recordings. Choose a new sequence.')
            folder,plan=output_plan(config,'Trial',trial,sequence,now,reserve=False)
            folder.mkdir(parents=True,exist_ok=True);final=plan['archive']
            state=root/'.project.json'
            data=json.loads(state.read_text(encoding='utf-8-sig')) if state.exists() else {'project':project,'last_trial':0}
            meta=json.loads(json.dumps(self.meta));meta.update(trial=trial,pending_capture=False,
                status='complete_with_error' if self.error else 'complete',saved_utc=datetime.now(timezone.utc).isoformat())
            for key in ('draft_trial','pending_output','pending_sequence','save_destination'):meta.pop(key,None)
            meta['files']={'raw':'raw.csv','events':'events.csv','metadata':'metadata.json'}
            self.meta['save_destination']=str(final);self.write_meta()
            tmp=final.with_name(final.name+'.'+uuid.uuid4().hex+'.tmp')
            with zipfile.ZipFile(tmp,'x',compression=zipfile.ZIP_DEFLATED) as z:
                z.write(work/'raw.csv','raw.csv');z.write(work/'events.csv','events.csv')
                z.writestr('metadata.json',json.dumps(meta,ensure_ascii=False,indent=2))
            with tmp.open('r+b') as f:f.flush();os.fsync(f.fileno())
            with zipfile.ZipFile(tmp) as z:
                if z.testzip() is not None:raise IOError('ZIP verification failed; pending files retained.')
                for name in ('raw.csv','events.csv'):
                    with z.open(name) as packed,(work/name).open('rb') as original:
                        if stream_digest(packed)!=stream_digest(original):raise IOError('Saved data verification failed.')
            if sys.platform=='win32':os.rename(tmp,final)
            else:os.link(tmp,final)
            # A published ZIP is authoritative even if the counter or cleanup fails.
            try:atomic_json(work/'metadata.json',{**self.meta,'status':'saved','saved_archive':str(final)})
            except OSError:pass
            self.pending_capture=False;self.meta=meta;self.files={'archive':final};self.folder=folder
            lease=getattr(self,'pending_lease',None)
            if lease:lease.close();self.pending_lease=None
            if hasattr(self,'_pre_recovery_error'):self.error=self._pre_recovery_error;del self._pre_recovery_error
            if trial.get('auto_trial_id'):
                data.setdefault('trial_sequences',{})[trial_prefix(trial).casefold()]=int(trial['trial_id'].rsplit('-',1)[1])
            try:atomic_json(state,data)
            except OSError:pass  # Next Save also scans published records for occupied IDs.
            try:shutil.rmtree(work)
            except OSError:pass  # Recovery recognizes save_destination + recording_id.
            return final,trial
        finally:
            for path in (tmp,lock):
                if path:
                    try:path.unlink(missing_ok=True)
                    except OSError:pass

    def delete_pending(self):
        if self.active:raise ValueError('Stop recording before deleting.')
        work=self.pending_directory()
        for attr in ('file','event_file'):
            f=getattr(self,attr,None)
            if f:f.close();setattr(self,attr,None)
        lease=getattr(self,'pending_lease',None)
        if lease:lease.close();self.pending_lease=None
        shutil.rmtree(work)
        self.pending_capture=False;self.folder=None;self.files={};self.events=[];self.duration=0.
        self.x=self.y=self.distance=0.;self.packets=0;self.trace.clear();self.history.clear();self.recent.clear()
        self.first_stimulus_stamp=None;self.auto_stop_deadline=None
        if hasattr(self,'_pre_recovery_error'):self.error=self._pre_recovery_error;del self._pre_recovery_error

    def recover_pending(self,work):
        work=Path(work);meta=json.loads((work/'metadata.json').read_text(encoding='utf-8-sig'))
        record=load_recording(work/'metadata.json')
        self.folder=work;self.pending_capture=True;self.pending_directory()
        self.files={k:work/name for k,name in (('raw','raw.csv'),('events','events.csv'),('metadata','metadata.json'))}
        self.active=False;self.file=None;self.event_file=None;self.meta=meta;self.params=meta['settings'];self.unit=record.unit
        self.events=[]
        with (work/'events.csv').open(newline='',encoding='utf-8-sig') as f:
            for item in csv.DictReader(f):item['time_s']=float(item['time_s']);self.events.append(item)
        self.duration=record.duration;self.trace=deque(record.rows[-20000:],maxlen=20000)
        self.history=deque(((r[1],r[2]) for r in record.rows[-20000:]),maxlen=20000)
        last=record.rows[-1];self.x,self.y,self.distance=last[1:];self.packets=max(0,len(record.rows)-1)
        self._pre_recovery_error=self.error;self.error=meta.get('error','')
        if meta.get('status')=='recording':self.error='Recovered after an interrupted recording; duration ends at the last retained event.'
        self.t0=time.perf_counter()-self.duration;self.first_stimulus_stamp=None
        onsets=[float(v['time_s']) for v in self.events if v['event']=='stimulus_onset']
        if onsets:self.first_stimulus_stamp=self.t0+min(onsets)
        self.post_stimulus_s=float(self.params.get('post_stimulus_s',0));self.auto_stop_deadline=None;self.auto_stop_requested=False
        self.meta.update(status='pending',pending_capture=True,duration_s=self.duration,events=self.events,error=self.error,packets=self.packets)
        self.write_meta()

    def start(self,*args,**kwargs):
        super().start(*args,**kwargs)
        with self.lock:
            self.meta['recording_id']=uuid.uuid4().hex
            self.write_meta()
    def stop(self):
        if self.pending_capture:
            with self.lock:
                if self.active:self.duration=time.perf_counter()-self.t0
                self.active=False
                for attr in ('file','event_file'):
                    f=getattr(self,attr,None)
                    if f:f.flush();os.fsync(f.fileno());f.close();setattr(self,attr,None)
                self.meta.update(events=self.events,duration_s=self.duration,packets=self.packets,
                                 ignored_absolute=self.absolute,status='pending',error=self.error)
                self.write_meta()
            return
        if 'archive' not in self.files:return super().stop()
        with self.lock:
            self.duration=time.perf_counter()-self.t0;self.active=False
            for attr in ('file','event_file'):
                f=getattr(self,attr,None)
                if f:f.flush();os.fsync(f.fileno());f.close();setattr(self,attr,None)
            self.meta.update(events=self.events,duration_s=self.duration,packets=self.packets,
                             ignored_absolute=self.absolute,status='complete_with_error' if self.error else 'complete',error=self.error)
            self.write_meta()
        final=self.files['archive'];tmp=final.with_name(final.name+'.'+uuid.uuid4().hex+'.tmp')
        work=self.files['raw'].parent
        meta=json.loads(json.dumps(self.meta))
        meta['files']={'raw':'raw.csv','events':'events.csv','metadata':'metadata.json'}
        try:
            with zipfile.ZipFile(tmp,'x',compression=zipfile.ZIP_DEFLATED) as z:
                z.write(self.files['raw'],'raw.csv');z.write(self.files['events'],'events.csv')
                z.writestr('metadata.json',json.dumps(meta,ensure_ascii=False,indent=2))
            with tmp.open('r+b') as f:f.flush();os.fsync(f.fileno())
            with zipfile.ZipFile(tmp) as z:
                if z.testzip() is not None:raise IOError('Archive validation failed; raw files retained.')
                for key in ('raw.csv','events.csv'):
                    with z.open(key) as packed, (work/key).open('rb') as original:
                        if stream_digest(packed)!=stream_digest(original):
                            raise IOError('Archive content verification failed; raw files retained.')
            # Publish a complete archive atomically, without replacing an existing file.
            # Windows rename refuses existing destinations; POSIX hard-link also
            # publishes without replacement. Failures retain the staging data.
            if sys.platform=='win32':os.rename(tmp,final)
            else:os.link(tmp,final)
            with zipfile.ZipFile(final) as z:
                if z.testzip() is not None:raise IOError('Final archive verification failed; raw files retained.')
            self.meta=meta
            shutil.rmtree(work)
        finally:tmp.unlink(missing_ok=True)


legacy_load_recording=load_recording

def load_recording(path):
    path=Path(path)
    if path.suffix.lower()!='.zip':return apply_database_metadata(legacy_load_recording(path))
    with tempfile.TemporaryDirectory(prefix='treadmill-read-') as tmp:
        with zipfile.ZipFile(path) as z:
            names=z.namelist()
            if any(names.count(name)!=1 for name in ('metadata.json','raw.csv','events.csv')):
                raise ValueError('Expected one metadata.json, raw.csv and events.csv in recording ZIP.')
            # Copy only exact known members; never extract archive paths.
            for name in ('metadata.json','raw.csv','events.csv'):
                info=z.getinfo(name)
                if info.file_size>2*1024**3:raise ValueError('Recording member exceeds 2 GiB limit.')
                with z.open(info) as src,(Path(tmp)/name).open('wb') as dst:shutil.copyfileobj(src,dst)
        record=legacy_load_recording(Path(tmp)/'metadata.json')
    record.source_path=path.resolve();record.metadata_path=None;record.archive_path=path.resolve();record.name=path.name
    h,rows,n,_=record.csv_preview;record.csv_preview=(h,rows,n,str(path)+' / raw.csv')
    return apply_database_metadata(record)


def source_fingerprint(path,meta):
    paths=[Path(path)]
    if Path(path).suffix.lower()=='.json':
        for kind in ('raw','events'):
            name=meta.get('files',{}).get(kind)
            if name:paths.append(Path(path).parent/basename_any(name))
    h=hashlib.sha256()
    for p in paths:
        h.update(p.name.encode())
        with p.open('rb') as f:
            for block in iter(lambda:f.read(1024*1024),b''):h.update(block)
    return h.hexdigest()


def analysis_signature(params,unit,post_ms,peak_ms):
    return json.dumps({'algorithm':ANALYSIS_VERSION,'latency':params,'unit':unit,'post_ms':post_ms,'peak_ms':peak_ms},sort_keys=True,separators=(',',':'))


def write_summary(path,rows):
    path=Path(path);path.parent.mkdir(parents=True,exist_ok=True)
    present=list(dict.fromkeys(k for r in rows for k in r))
    preferred=[k for k,_ in DATABASE_COLUMNS] if 'DATABASE_COLUMNS' in globals() else []
    tail=['stimulus_index','stimulus_id','stimulus_count','post_window_ms','peak_window_ms','post_status','source']
    fields=[k for k in preferred if k in present and k not in tail]+[k for k in present if k not in preferred and k not in tail]+[k for k in tail if k in present]
    fields=fields or ['recording_id','stimulus_index','status']
    tmp=path.with_name('.summary-'+uuid.uuid4().hex+'.tmp')
    try:
        with tmp.open('w',newline='',encoding='utf-8-sig') as f:
            writer=csv.DictWriter(f,fieldnames=fields);writer.writeheader();writer.writerows(rows);f.flush();os.fsync(f.fileno())
        os.replace(tmp,path)
    finally:tmp.unlink(missing_ok=True)



# v1: per-project SQLite catalog. Raw sources are never rewritten by metadata edits.
import sqlite3
from contextlib import closing

DB_NAME = 'project.sqlite'
DB_SCHEMA = 1
DATABASE_COLUMNS = [
    ('animal_id','Animal'),('group','Group'),('airspeed','Air (m/s)'),('sequence','Sequence'),
    ('trial_id','Trial'),('corrected_latency_ms','Corrected (ms)'),('raw_latency_ms','Raw (ms)'),
    ('status','Status'),('peak_speed','Peak speed'),('displacement','Displacement'),
    ('post_path_length','Path length'),('notes','Notes'),('recording_id','Recording ID'),
    ('stimulus_index','Stimulus'),('stimulus_count','Stimulus count'),('post_window_ms','Post-onset (ms)'),
    ('peak_window_ms','Peak window (ms)'),('post_status','Post-onset status'),('source','Source')]
DEFAULT_DB_SORT = [('animal_id',False),('airspeed',False),('sequence',False)]

def utc_now():return datetime.now(timezone.utc).isoformat()

def animal_parts(animal):
    match=re.fullmatch(r'([CE])(\d+)\.(\d+)',str(animal).strip(),re.I)
    return (int(match[2]),int(match[3])) if match else (None,None)

def group_from_animal(animal):
    match=re.match(r'^([CE])(?=\d)',str(animal).strip(),re.I)
    return {'c':'Control','e':'Experiment'}.get(match[1].lower()) if match else None

def condition_key(animal,speed):
    value=finite_number(speed)
    return str(animal).strip().casefold(),format(value,'.12g') if value is not None else str(speed)

def trial_sequence(trial):
    tail=str(trial).rsplit('-',1)[-1]
    return int(tail) if tail.isdigit() else None

def natural_value(value):
    return tuple((0,int(s)) if s.isdigit() else (1,s.casefold()) for s in re.split(r'(\d+)',str(value)))

def sorted_database_rows(rows,order):
    rows=list(rows)
    for field,descending in reversed(order):
        def key(row):
            value=row.get(field)
            if field in ('airspeed','sequence','raw_latency_ms','corrected_latency_ms','stimulus_index'):
                number=finite_number(value);return (number is None,number or 0.)
            return (value in (None,''),natural_value(value or ''))
        rows.sort(key=key,reverse=bool(descending))
    return rows

def source_events(path,meta):
    path=Path(path);events=meta.get('events',[])
    if path.suffix.lower()=='.zip':
        with zipfile.ZipFile(path) as z:
            with z.open('events.csv') as f:
                import io
                events=list(csv.DictReader(io.TextIOWrapper(f,encoding='utf-8-sig',newline='')))
    elif meta.get('files',{}).get('events'):
        p=path.parent/basename_any(meta['files']['events'])
        if p.exists():
            with p.open(newline='',encoding='utf-8-sig') as f:events=list(csv.DictReader(f))
    return sorted(events,key=lambda e:float(e['time_s']))

def project_for_path(path):
    path=Path(path).resolve()
    for root in path.parents:
        if (root/DB_NAME).is_file() or (root/'.project.json').is_file():return root
    return None

class ProjectStore:
    """Short-lived connections are local to the calling UI/worker thread."""
    analysis_numbers=('on_s','movement_s','raw_latency_ms','corrected_latency_ms','airflow_delay_ms',
        'threshold','window_ms','confirmation_ms','baseline_ms','response_ms','post_window_ms','peak_window_ms',
        'peak_speed','displacement','post_path_length')
    analysis_text=('status','quality','unit','post_status','time_basis','software_version')
    def __init__(self,root):
        self.root=Path(root).resolve();self.root.mkdir(parents=True,exist_ok=True);self.path=self.root/DB_NAME
        self.db=sqlite3.connect(self.path,timeout=30);self.db.row_factory=sqlite3.Row
        self.db.execute('PRAGMA foreign_keys=ON');self.db.execute('PRAGMA busy_timeout=30000')
        version=self.db.execute('PRAGMA user_version').fetchone()[0]
        if version>DB_SCHEMA:self.close();raise ValueError('This database requires a newer TreadScope version.')
        if not version:
            self.db.executescript('''
BEGIN IMMEDIATE;
CREATE TABLE IF NOT EXISTS recordings (
 recording_id TEXT PRIMARY KEY, project TEXT NOT NULL, animal_id TEXT NOT NULL DEFAULT '',
 treatment_group TEXT NOT NULL DEFAULT '', airspeed REAL, trial_id TEXT NOT NULL DEFAULT '', sequence INTEGER,
 lab_number INTEGER, animal_number INTEGER, notes TEXT NOT NULL DEFAULT '', operator TEXT NOT NULL DEFAULT '',
 dose TEXT NOT NULL DEFAULT '', unit TEXT NOT NULL, source_file TEXT NOT NULL, fingerprint TEXT NOT NULL,
 payload_key TEXT NOT NULL, file_stamp TEXT NOT NULL, original_metadata_json TEXT NOT NULL, metadata_edited INTEGER NOT NULL DEFAULT 0,
 metadata_revision INTEGER NOT NULL DEFAULT 0, availability TEXT NOT NULL, is_test INTEGER NOT NULL DEFAULT 0,
 utc_start TEXT, duration_s REAL, stimulus_count INTEGER NOT NULL DEFAULT 0, imported_utc TEXT NOT NULL, updated_utc TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS recording_condition ON recordings(animal_id,airspeed,sequence);
CREATE INDEX IF NOT EXISTS recording_path ON recordings(source_file);
CREATE TABLE IF NOT EXISTS stimuli (
 recording_id TEXT NOT NULL REFERENCES recordings(recording_id), event_index INTEGER NOT NULL,
 event TEXT NOT NULL, time_s REAL NOT NULL, stimulus_index INTEGER, stimulus_id TEXT, source TEXT, event_json TEXT NOT NULL,
 PRIMARY KEY(recording_id,event_index));
CREATE TABLE IF NOT EXISTS sequence_counters (animal_key TEXT NOT NULL,speed_key TEXT NOT NULL,last_sequence INTEGER NOT NULL,
 PRIMARY KEY(animal_key,speed_key));
CREATE TABLE IF NOT EXISTS metadata_history (
 edit_id INTEGER PRIMARY KEY, recording_id TEXT NOT NULL REFERENCES recordings(recording_id), edited_utc TEXT NOT NULL,
 revision INTEGER NOT NULL, old_json TEXT NOT NULL, new_json TEXT NOT NULL, reason TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS preferences (key TEXT PRIMARY KEY,value_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS migration_log (key TEXT PRIMARY KEY,completed_utc TEXT NOT NULL,details TEXT NOT NULL);
'''+'''CREATE TABLE IF NOT EXISTS analyses (
 recording_id TEXT NOT NULL REFERENCES recordings(recording_id), stimulus_index INTEGER NOT NULL,
 analysis_signature TEXT NOT NULL, fingerprint TEXT NOT NULL, calculated_utc TEXT NOT NULL,
 '''+',\n '.join(k+' REAL' for k in self.analysis_numbers)+',\n '+',\n '.join(k+' TEXT' for k in self.analysis_text)+''',
 payload_json TEXT NOT NULL, PRIMARY KEY(recording_id,stimulus_index,analysis_signature,fingerprint));
CREATE INDEX IF NOT EXISTS analysis_lookup ON analyses(recording_id,stimulus_index,calculated_utc);
CREATE VIEW IF NOT EXISTS recording_catalog AS
 SELECT recording_id,project,animal_id,treatment_group AS group_name,airspeed AS airspeed_m_s,sequence,trial_id,
 lab_number,animal_number,notes,operator,unit,availability,is_test,metadata_revision,utc_start,duration_s,source_file,
 stimulus_count FROM recordings;
CREATE VIEW IF NOT EXISTS trial_analysis AS
 SELECT r.project,r.animal_id,r.treatment_group AS group_name,r.airspeed AS airspeed_m_s,r.sequence,r.trial_id,
 a.corrected_latency_ms,a.raw_latency_ms,COALESCE(a.status,'Not calculated') AS status,
 a.peak_speed,a.displacement,a.post_path_length,r.unit,r.lab_number,r.animal_number,r.notes,r.operator,
 r.recording_id,r.source_file,r.availability,r.is_test,r.metadata_revision,r.utc_start,
 a.analysis_signature,a.calculated_utc,a.software_version,a.quality,a.threshold,a.window_ms,a.confirmation_ms,
 a.baseline_ms,a.response_ms,a.airflow_delay_ms,s.time_s AS on_s,a.movement_s,
 s.stimulus_index,r.stimulus_count,a.post_window_ms,a.peak_window_ms,a.post_status,s.source
 FROM recordings r JOIN stimuli s ON s.recording_id=r.recording_id AND s.stimulus_index IS NOT NULL
 LEFT JOIN analyses a ON a.rowid=(SELECT b.rowid FROM analyses b WHERE b.recording_id=r.recording_id
 AND b.stimulus_index=s.stimulus_index AND b.fingerprint=r.fingerprint
 ORDER BY b.calculated_utc DESC,b.rowid DESC LIMIT 1);
PRAGMA user_version=1;
COMMIT;
''')
    def close(self):self.db.close()
    def __enter__(self):return self
    def __exit__(self,*args):self.close()
    def preference(self,key,default):
        item=self.db.execute('SELECT value_json FROM preferences WHERE key=?',(key,)).fetchone()
        return json.loads(item[0]) if item else default
    def set_preference(self,key,value):
        with self.db:self.db.execute('INSERT OR REPLACE INTO preferences VALUES (?,?)',(key,json.dumps(value)))
    def catalog(self):
        return [dict(r,group=r['treatment_group']) for r in self.db.execute("SELECT recordings.*, (SELECT group_concat(DISTINCT source) FROM stimuli WHERE stimuli.recording_id=recordings.recording_id) AS source FROM recordings")]
    def lookup(self,path):
        try:relative=Path(path).resolve().relative_to(self.root).as_posix()
        except ValueError:return None
        row=self.db.execute("SELECT * FROM recordings WHERE source_file=? AND availability!='missing'",(relative,)).fetchone()
        return dict(row) if row else None
    def reserve_seen(self,animal,speed,sequence):
        if sequence is None:return
        a,s=condition_key(animal,speed)
        self.db.execute('INSERT INTO sequence_counters VALUES (?,?,?) ON CONFLICT(animal_key,speed_key) DO UPDATE SET last_sequence=MAX(last_sequence,excluded.last_sequence)',(a,s,sequence))
    def next_sequence(self,animal,speed):
        a,s=condition_key(animal,speed)
        row=self.db.execute('SELECT last_sequence FROM sequence_counters WHERE animal_key=? AND speed_key=?',(a,s)).fetchone()
        return (row[0] if row else 0)+1
    def file_stamp(self,path,meta):
        paths=[Path(path)]
        if Path(path).suffix.lower()=='.json':
            paths.extend(Path(path).parent/basename_any(meta['files'][k]) for k in ('raw','events') if meta.get('files',{}).get(k))
        return json.dumps([(p.name,p.stat().st_size,p.stat().st_mtime_ns) for p in paths if p.exists()])
    def import_record(self,path):
        path=Path(path).resolve()
        if not path.is_relative_to(self.root):raise ValueError('Recording must be inside the project folder.')
        rel=path.relative_to(self.root).as_posix()
        previous=self.lookup(path)
        if previous and previous['availability']!='unreadable' and previous['file_stamp']==self.file_stamp(path,json.loads(previous['original_metadata_json'])):
            return previous['recording_id']
        meta=recording_metadata(path)
        if not isinstance(meta,dict) or not isinstance(meta.get('files'),dict) or not meta['files'].get('raw'):return None
        if meta.get('status') not in ('complete','complete_with_error'):return None
        events=source_events(path,meta);fingerprint=source_fingerprint(path,meta)
        # Filename-independent fallback identity for legacy files, including restored/renamed files.
        identity_meta={k:v for k,v in meta.items() if k!='files'}
        payload=hashlib.sha256(json.dumps(identity_meta,sort_keys=True,ensure_ascii=False).encode())
        if not meta.get('recording_id'):
            if path.suffix.lower()=='.zip':
                with zipfile.ZipFile(path) as z:
                    for name in ('raw.csv','events.csv'):
                        with z.open(name) as f:payload.update(stream_digest(f))
            else:
                for name in ('raw','events'):
                    member=meta['files'].get(name)
                    if member and (path.parent/basename_any(member)).exists():
                        with (path.parent/basename_any(member)).open('rb') as f:payload.update(stream_digest(f))
        payload_key=payload.hexdigest();rid=str(meta.get('recording_id') or 'legacy-'+payload_key)
        old=self.db.execute('SELECT * FROM recordings WHERE recording_id=?',(rid,)).fetchone()
        if old and old['source_file']!=rel and (self.root/old['source_file']).is_file():
            raise ValueError('Duplicate recording ID; original retained at '+old['source_file'])
        folders=[v.casefold() for v in path.relative_to(self.root).parts[:-1]]
        state='deleted' if 'delete' in folders else 'test_deleted' if 'test delete' in folders else 'active'
        onsets=[e for e in events if e.get('event','stimulus_onset')=='stimulus_onset' and e.get('source') in ('arduino','ttl','simulated')]
        trial=meta.get('trial',{});animal=str(trial.get('cricket_id',''));lab,individual=animal_parts(animal)
        sequence=trial_sequence(trial.get('trial_id',''));now=utc_now()
        initial=dict(recording_id=rid,project=self.root.name,animal_id=animal,treatment_group=str(trial.get('treatment','')),
            airspeed=finite_number(trial.get('air_speed_m_s')),trial_id=str(trial.get('trial_id','')),sequence=sequence,
            lab_number=lab,animal_number=individual,notes=str(trial.get('notes','')),operator=str(trial.get('operator','')),
            dose=str(trial.get('dose_with_unit','')),unit=meta.get('unit','recorded units'),source_file=rel,fingerprint=fingerprint,
            payload_key=payload_key,file_stamp=self.file_stamp(path,meta),original_metadata_json=json.dumps(meta,ensure_ascii=False),metadata_edited=0,metadata_revision=0,
            availability=state,is_test=int(str(meta.get('mode','Trial')).lower()=='test'),utc_start=meta.get('utc_start'),
            duration_s=finite_number(meta.get('duration_s')),stimulus_count=len(onsets),imported_utc=now,updated_utc=now)
        if not old:
            self.db.execute('INSERT INTO recordings ('+','.join(initial)+') VALUES ('+','.join('?' for _ in initial)+')',tuple(initial.values()))
        else:
            fields=('unit','source_file','fingerprint','payload_key','file_stamp','availability','is_test','duration_s','stimulus_count')
            self.db.execute('UPDATE recordings SET '+','.join(k+'=?' for k in fields)+',updated_utc=? WHERE recording_id=?',tuple(initial[k] for k in fields)+(now,rid))
        self.reserve_seen(animal,initial['airspeed'],sequence)
        if old:self.reserve_seen(old['animal_id'],old['airspeed'],old['sequence'])
        self.db.execute('DELETE FROM stimuli WHERE recording_id=?',(rid,));onset_index=0
        for i,e in enumerate(events):
            t=float(e['time_s'])
            if not math.isfinite(t) or t<0:raise ValueError('Invalid stimulus timestamp.')
            kind=e.get('event','stimulus_onset');idx=None
            if kind=='stimulus_onset' and e.get('source') in ('arduino','ttl','simulated'):onset_index+=1;idx=onset_index
            self.db.execute('INSERT INTO stimuli VALUES (?,?,?,?,?,?,?,?)',(rid,i,kind,t,idx,str(e.get('trial_id','')),e.get('source'),json.dumps(e,ensure_ascii=False)))
        return rid
    def sync(self,progress=None):
        errors=[];seen=set();candidates=[]
        for base,dirs,files in os.walk(self.root):
            dirs[:]=[d for d in dirs if not d.startswith('.') and d.casefold() not in ('database backups','backups')]
            candidates.extend(Path(base)/f for f in files if not f.startswith('.') and Path(f).suffix.lower() in ('.zip','.json'))
        with self.db:
            for i,path in enumerate(sorted(candidates)):
                if progress:progress(f'Indexing {i+1}/{len(candidates)}: {path.name}')
                self.db.execute('SAVEPOINT import_one')
                try:
                    rid=self.import_record(path)
                    if rid:seen.add(rid)
                    self.db.execute('RELEASE import_one')
                except Exception as ex:
                    self.db.execute('ROLLBACK TO import_one');self.db.execute('RELEASE import_one');errors.append(path.name+': '+str(ex))
                    self.db.execute("UPDATE recordings SET availability='unreadable' WHERE source_file=?",(path.resolve().relative_to(self.root).as_posix(),))
            # Retain tombstones and sequence counters, never silently drop missing recordings.
            for row in self.db.execute('SELECT recording_id,source_file FROM recordings').fetchall():
                if row['recording_id'] not in seen and not (self.root/row['source_file']).is_file():
                    self.db.execute("UPDATE recordings SET availability='missing' WHERE recording_id=?",(row['recording_id'],))
            state=self.root/'.project.json'
            if state.exists():
                try:
                    for key,value in json.loads(state.read_text(encoding='utf-8-sig')).get('trial_sequences',{}).items():
                        animal,sep,speed=key.rpartition('-')
                        if sep:self.reserve_seen(animal,speed,int(value))
                except (ValueError,TypeError) as ex:errors.append('Legacy counter: '+str(ex))
            self.migrate_summary(errors)
        return errors
    def migrate_summary(self,errors):
        if self.db.execute("SELECT 1 FROM migration_log WHERE key='summary.csv' ").fetchone():return
        path=self.root/'summary.csv'
        if path.exists():
            try:
                with path.open(newline='',encoding='utf-8-sig') as f:rows=list(csv.DictReader(f))
                for row in rows:
                    record=self.lookup(self.root/str(row.get('source_file','')).replace('\\','/'))
                    if not record:continue
                    if row.get('analysis_signature') and row.get('fingerprint')==record['fingerprint']:
                        self.save_analysis({**row,'recording_id':record['recording_id']})
            except Exception as ex:
                errors.append('Legacy summary migration: '+str(ex));return
        self.db.execute('INSERT INTO migration_log VALUES (?,?,?)',('summary.csv',utc_now(),'Imported compatible results; legacy CSV left unchanged.'))
    def save_analysis(self,row):
        signature=row.get('analysis_signature')
        if not signature:return
        values={k:row[k] for k in ('recording_id','stimulus_index','analysis_signature','fingerprint')}
        values['calculated_utc']=row.get('calculated_utc') or utc_now()
        values.update({k:finite_number(row.get(k)) for k in self.analysis_numbers})
        values.update({k:str(row.get(k,'') or '') for k in self.analysis_text})
        values['payload_json']=json.dumps(row,ensure_ascii=False)
        self.db.execute('INSERT OR REPLACE INTO analyses ('+','.join(values)+') VALUES ('+','.join('?' for _ in values)+')',tuple(values.values()))
    def cached(self,rid,index,signature,fingerprint):
        row=self.db.execute('SELECT payload_json FROM analyses WHERE recording_id=? AND stimulus_index=? AND analysis_signature=? AND fingerprint=?',(rid,index,signature,fingerprint)).fetchone()
        return json.loads(row[0]) if row else None
    def edit(self,ids,updates,reason='Metadata correction',expected=None):
        ids=list(dict.fromkeys(ids));allowed={'animal_id','group','airspeed','sequence','notes','operator'}
        if not ids or not updates or set(updates)-allowed:raise ValueError('Choose recordings and supported metadata fields.')
        with self.db:
            self.db.execute('BEGIN IMMEDIATE')
            originals=[];proposed=[]
            for rid in ids:
                old=self.db.execute('SELECT * FROM recordings WHERE recording_id=?',(rid,)).fetchone()
                if old is None:raise ValueError('Recording no longer exists.')
                old=dict(old)
                if expected is not None and expected.get(rid)!=old['metadata_revision']:raise ValueError('Metadata changed while this editor was open. Reopen and try again.')
                new=dict(old);new.update({('treatment_group' if k=='group' else k):v for k,v in updates.items()})
                animal=str(new['animal_id']).strip();group=new['treatment_group']
                if 'group' in updates and re.match(r'^[CE](?=\d)',animal,re.I):animal=('C' if group=='Control' else 'E')+animal[1:]
                elif 'animal_id' in updates:group=group_from_animal(animal) or group
                if not animal or safe_component(animal)!=animal:raise ValueError('Animal ID must be nonempty and valid in a filename.')
                if group not in ('Control','Experiment'):raise ValueError('Group must be Control or Experiment.')
                speed=finite_number(new['airspeed'])
                if speed is None or speed<0:raise ValueError('Air speed must be a finite nonnegative number in m/s.')
                seq=new['sequence']
                if seq is not None:
                    if int(seq)!=float(seq) or int(seq)<0:raise ValueError('Sequence must be a nonnegative integer.')
                    seq=int(seq)
                elif any(k in updates for k in ('animal_id','airspeed','group')):
                    raise ValueError('This legacy Trial ID has no numeric sequence. Assign a sequence before changing its condition.')
                new.update(animal_id=animal,treatment_group=group,airspeed=speed,sequence=seq,
                    lab_number=animal_parts(animal)[0],animal_number=animal_parts(animal)[1])
                if any(k in updates for k in ('animal_id','airspeed','group','sequence')):
                    new['trial_id']=f'{animal}-{speed:.12g}-{seq:03d}'
                originals.append(old);proposed.append(new)
            # Reserve unchanged IDs first, including cleaned/deleted recordings.
            occupied={str(item['trial_id']).casefold() for item in self.catalog()
                      if item['recording_id'] not in ids}
            for old,new in zip(originals,proposed):
                if new['trial_id']==old['trial_id']:
                    occupied.add(str(new['trial_id']).casefold())
            for old,new in zip(originals,proposed):
                if new['trial_id']==old['trial_id']:continue
                base=new['trial_id'];candidate=base;suffix=0
                while candidate.casefold() in occupied:
                    suffix+=1;candidate=f'{base}-{suffix}'
                new['trial_id']=candidate;occupied.add(candidate.casefold())
            fields=('animal_id','treatment_group','airspeed','sequence','trial_id','lab_number','animal_number','notes','operator')
            for old,new in zip(originals,proposed):
                if all(old[k]==new[k] for k in fields):continue
                revision=old['metadata_revision']+1;now=utc_now()
                self.db.execute('UPDATE recordings SET '+','.join(k+'=?' for k in fields)+',metadata_edited=1,metadata_revision=?,updated_utc=? WHERE recording_id=?',tuple(new[k] for k in fields)+(revision,now,new['recording_id']))
                self.db.execute('INSERT INTO metadata_history(recording_id,edited_utc,revision,old_json,new_json,reason) VALUES (?,?,?,?,?,?)',
                    (new['recording_id'],now,revision,json.dumps({k:old[k] for k in fields},ensure_ascii=False),json.dumps({k:new[k] for k in fields},ensure_ascii=False),reason))
                self.reserve_seen(new['animal_id'],new['airspeed'],new['sequence'])
        return proposed
    def backup(self,destination):
        destination=Path(destination)
        if destination.resolve()==self.path:raise ValueError('Choose a different backup filename.')
        if destination.exists():raise ValueError('Choose a new filename; existing backups are not overwritten.')
        with closing(sqlite3.connect(destination)) as copy:self.db.backup(copy)


def apply_database_metadata(record):
    path=getattr(record,'archive_path',None) or getattr(record,'metadata_path',None) or record.source_path
    root=project_for_path(path)
    if not root or not (root/DB_NAME).is_file():return record
    with ProjectStore(root) as store:row=store.lookup(path)
    if row:
        if not hasattr(record,'original_meta'):record.original_meta=json.loads(json.dumps(record.meta))
        record.meta={**record.meta,'recording_id':row['recording_id'],'trial':{**record.meta.get('trial',{}),
            'project':row['project'],'cricket_id':row['animal_id'],'treatment':row['treatment_group'],
            'air_speed_m_s':row['airspeed'],'trial_id':row['trial_id'],'notes':row['notes'],'operator':row['operator']}}
    return record


def post_metrics(record,onset,params,post_ms,peak_ms,next_onset):
    end=onset+post_ms/1000;window=peak_ms/1000
    if end>min(record.duration,next_onset)+1e-10:
        return dict(peak_speed='',displacement='',post_path_length='',post_status='Insufficient post-onset recording')
    def state(t):return record.rows[max(0,bisect.bisect_right(record.times,t+1e-10)-1)]
    first=state(onset);last=state(end)
    distance=math.hypot(last[1]-first[1],last[2]-first[2])
    # Fixed-duration trailing net speed, using only windows entirely after onset.
    times={onset+window,end}
    for t in record.times:
        if onset+window<=t<=end:times.add(t)
        if onset+window<=t+window<=end:times.add(t+window)
    peak=max((math.hypot(state(t)[1]-state(t-window)[1],state(t)[2]-state(t-window)[2])/window for t in times),default=0.)
    return dict(peak_speed=peak,displacement=distance,post_path_length=last[3]-first[3],post_status='Complete')


def scan_project(root,params,unit,post_ms,peak_ms,calculate=False,progress=None,only_source=None,synchronize=True):
    root=Path(root).resolve();signature=analysis_signature(params,unit,post_ms,peak_ms);rows=[];saved=[]
    with ProjectStore(root) as store:
        errors=store.sync(progress) if synchronize else []
        entries=[r for r in store.catalog() if r['availability'] in ('active','test_deleted') and not r['is_test']]
        for number,item in enumerate(entries):
            path=root/item['source_file'];rid=item['recording_id'];record=None
            if progress:progress(f'Checking {number+1}/{len(entries)}: {path.name}')
            base=dict(project=item['project'],animal_id=item['animal_id'],group=item['treatment_group'],airspeed=item['airspeed'],
                sequence=item['sequence'],trial_id=item['trial_id'],notes=item['notes'],operator=item['operator'],
                lab_number=item['lab_number'],animal_number=item['animal_number'],metadata_revision=item['metadata_revision'],
                recording_id=rid,source_file=item['source_file'],fingerprint=item['fingerprint'],unit=item['unit'],
                stimulus_count=item['stimulus_count'],include_simulated=bool(params.get('include_simulated',False)),
                test_deleted=item['availability']=='test_deleted')
            try:
                if not path.resolve().is_relative_to(root):raise ValueError('Source path is outside this project.')
                events=[dict(r) for r in store.db.execute('SELECT * FROM stimuli WHERE recording_id=? AND stimulus_index IS NOT NULL ORDER BY stimulus_index',(rid,))]
                selected=[e for e in events if e['source'] in stimulus_sources(params)]
                if not selected:
                    rows.append({**base,'stimulus_index':'','status':'Simulated excluded' if events else 'No stimulus',
                                 'source':','.join(sorted({e['source'] for e in events if e['source']}))});continue
                for j,event in enumerate(selected):
                    common={**base,'stimulus_index':str(event['stimulus_index']),'stimulus_id':event['stimulus_id'] or event['stimulus_index'],
                        'on_s':event['time_s'],'source':event['source']}
                    old=store.cached(rid,event['stimulus_index'],signature,item['fingerprint'])
                    if item['unit']!=unit:
                        row={**common,'status':'Unit mismatch','analysis_signature':'','raw_latency_ms':'','corrected_latency_ms':''}
                    elif old:row={**old,**common}
                    elif calculate and (only_source is None or path.resolve()==Path(only_source).resolve()):
                        if record is None:
                            record=load_recording(path);results=detect_latencies(record,params)
                            if source_fingerprint(path,recording_metadata(path))!=item['fingerprint']:raise ValueError('Source changed during calculation; retry.')
                        result=results[j]
                        row={**result,**common,'analysis_signature':signature,'calculated_utc':utc_now(),
                            'post_window_ms':post_ms,'peak_window_ms':peak_ms,'peak_speed':'','displacement':'','post_path_length':'','post_status':''}
                        if result['status']=='Response':
                            next_on=selected[j+1]['time_s'] if j+1<len(selected) else math.inf
                            row.update(post_metrics(record,float(result['movement_s']),params,post_ms,peak_ms,next_on))
                        saved.append(row)
                    else:
                        exists=store.db.execute('SELECT 1 FROM analyses WHERE recording_id=? AND stimulus_index=? LIMIT 1',(rid,event['stimulus_index'])).fetchone()
                        row={**common,'status':'Needs recalculation' if exists else 'Not calculated','analysis_signature':'','raw_latency_ms':'','corrected_latency_ms':''}
                    rows.append(row)
            except Exception as ex:errors.append(path.name+': '+str(ex))
        if saved:
            with store.db:
                for row in saved:store.save_analysis(row)
    return rows,errors


def deleted_recordings(root):
    root=Path(root).resolve();items=[]
    for folder in ('Delete','Test Delete'):
        for path in sorted((root/folder).rglob('*')):
            if not path.is_file() or path.suffix.lower() not in ('.zip','.json'):continue
            if not path.resolve().is_relative_to(root/folder):continue
            try:
                meta=recording_metadata(path)
                if not isinstance(meta,dict) or not meta.get('files',{}).get('raw'):continue
                trial=meta.get('trial',{})
                if (root/DB_NAME).exists():
                    with ProjectStore(root) as store:current=store.lookup(path)
                    if current:trial={**trial,'cricket_id':current['animal_id'],'trial_id':current['trial_id']}
                items.append((path,folder,trial.get('cricket_id',''),trial.get('trial_id','')))
            except Exception:continue
    return items


def restore_trial_file(root,path):
    root=Path(root).resolve();path=Path(path).resolve()
    if not path.is_relative_to(root) or path.relative_to(root).parts[0] not in ('Delete','Test Delete'):
        raise ValueError('Choose a recording from this project Delete or Cleaning Trial folder.')
    if path.suffix.lower()=='.zip':
        destination=root/path.name
        if destination.exists():destination=root/(path.stem+'-restored-'+uuid.uuid4().hex[:8]+path.suffix)
        shutil.move(str(path),str(destination))
    else:
        record=load_recording(path);folder,_=move_recording_to_delete(record,root,'Restored');destination=folder/path.name
    return destination


class ReplayLatencyWorker(QThread):
    completed=pyqtSignal(object);failed=pyqtSignal(str)
    def __init__(self,record,params,root,post_ms,peak_ms):
        super().__init__();self.record=record;self.params=params.copy();self.root=root;self.post_ms=post_ms;self.peak_ms=peak_ms
    def run(self):
        try:
            path=Path(getattr(self.record,'archive_path',None) or getattr(self.record,'metadata_path',None) or self.record.source_path).resolve()
            if self.root and not any(p.casefold()=='delete' for p in path.relative_to(self.root).parts[:-1]):
                rows,errors=scan_project(self.root,self.params,self.record.unit,self.post_ms,self.peak_ms,True,only_source=path)
                result=[r for r in rows if r.get('stimulus_index') and (self.root/r['source_file']).resolve()==path]
                if not result and errors:raise ValueError('\n'.join(errors))
                self.completed.emit(result)
            else:self.completed.emit(detect_latencies(self.record,self.params))
        except Exception as ex:self.failed.emit(str(ex))


class ProjectAnalysisWorker(QThread):
    completed=pyqtSignal(object);failed=pyqtSignal(str);progress=pyqtSignal(str)
    def __init__(self,root,params,unit,post_ms,peak_ms,calculate,synchronize=True):
        super().__init__();self.args=(root,params.copy(),unit,post_ms,peak_ms,calculate);self.synchronize=synchronize
    def run(self):
        try:self.completed.emit(scan_project(*self.args,progress=self.progress.emit,synchronize=self.synchronize))
        except Exception as ex:self.failed.emit(str(ex))


def finite_number(v):
    try:
        n=float(v);return n if math.isfinite(n) else None
    except (ValueError,TypeError):return None


def quantile(values,p):
    values=sorted(values);k=(len(values)-1)*p;lo=int(k);hi=min(lo+1,len(values)-1)
    return values[lo]+(values[hi]-values[lo])*(k-lo)


def stat_points(rows,metric,level):
    points=[]
    for r in rows:
        if is_test_deleted(r):continue
        value=finite_number(r.get(metric));speed=finite_number(r.get('airspeed'))
        if r.get('status')!='Response' or value is None:continue
        if metric=='corrected_latency_ms' and value<0:continue
        if metric in ('peak_speed','displacement','post_path_length') and r.get('post_status')!='Complete':continue
        points.append(dict(value=value,speed=speed,animal=str(r.get('animal_id','')).strip(),group=r.get('group','') or 'Unspecified',unit=r.get('unit',''),n=1,rows=[r]))
    if level=='All trials':return points
    groups={}
    for p in points:
        if not p['animal']:continue
        key=(p['animal'],p['group'],p['speed'],p['unit']);groups.setdefault(key,[]).append(p)
    return [dict(animal=a,group=g,speed=s,unit=u,value=statistics.median([p['value'] for p in v]),n=len(v),rows=[r for p in v for r in p['rows']]) for (a,g,s,u),v in groups.items()]


def is_test_deleted(row):
    return str(row.get('test_deleted','')).lower() in ('true','1')


class TrialSummaryModel(CsvPreviewModel):
    def __init__(self,parent=None):super().__init__(parent);self.excluded=set()
    def data(self,index,role=Qt.ItemDataRole.DisplayRole):
        if index.isValid() and index.row() in self.excluded:
            if role==Qt.ItemDataRole.ForegroundRole:return QColor('#858585')
            if role==Qt.ItemDataRole.BackgroundRole:return QColor('#eeeeee')
            if role==Qt.ItemDataRole.ToolTipRole:return 'Cleaning Trial: retained for inspection; excluded from statistics.'
        return super().data(index,role)


def axis_ticks(low,high,target=5):
    span=high-low
    if span<=0:span=max(abs(low)*.1,1);low-=span/2;high+=span/2
    rough=(high-low)/max(2,target);power=10**math.floor(math.log10(rough))
    step=next(v for v in (1,2,2.5,5,10) if v*power>=rough)*power
    low=math.floor(low/step)*step;high=math.ceil(high/step)*step
    return low,high,step,[low+i*step for i in range(round((high-low)/step)+1)]


def tick_label(value,step):
    if abs(value)<step*1e-8:value=0
    if abs(value)>=1e6 or (step<.001):return f'{value:.3g}'
    decimals=max(0,-math.floor(math.log10(step)))+(1 if abs(step/10**math.floor(math.log10(step))-2.5)<1e-8 else 0)
    return f'{value:.{decimals}f}'


def individual_summaries(rows,metric):
    groups={}
    for point in stat_points(rows,metric,'All trials'):
        if point['animal']:
            key=(point['group'],point['animal'],point['speed'],point['unit'])
            groups.setdefault(key,[]).append(point)
    result=[]
    for (g,a,s,u),items in sorted(groups.items(),key=lambda item:(item[0][0],[(int(t) if t.isdigit() else t) for t in re.split(r'(\d+)',item[0][1])],item[0][2] if item[0][2] is not None else -1)):
        v=[p['value'] for p in items]
        result.append(dict(group=g,animal=a,speed=s,unit=u,value=statistics.median(v),q1=quantile(v,.25),q3=quantile(v,.75),n=len(v),mean=statistics.mean(v),values=v,items=items,rows=[r for pt in items for r in pt['rows']]))
    return result


class HorizontalRangeControl(QWidget):
    """Two handles resize the domain; dragging the selection pans it."""
    changed=pyqtSignal(float,float)
    def __init__(self):
        super().__init__();self.setFixedHeight(20);self.setMinimumWidth(100);self.full=(0.,1.);self.selected=(0.,1.);self.drag=None
        self.setToolTip('Drag either end to zoom. Drag the blue selection to pan the horizontal range.')
    def synchronize(self,full,selected):self.full=full;self.selected=selected;self.update()
    def fraction(self,x):return max(0.,min(1.,(x-8)/max(1,self.width()-16)))
    def paintEvent(self,event):
        p=QPainter(self);p.setRenderHint(QPainter.RenderHint.Antialiasing);a,b=self.full;c,d=self.selected
        x=lambda t:8+(t-a)/max(1e-12,b-a)*(self.width()-16)
        p.setPen(QPen(QColor('#b8b8b8'),2));p.drawLine(QPointF(8,10),QPointF(self.width()-8,10))
        p.setPen(QPen(QColor('#0078c8'),2));p.drawLine(QPointF(x(c),10),QPointF(x(d),10))
        for t in (c,d):p.setPen(QPen(QColor('#555555'),1));p.setBrush(QColor('#fafafa'));p.drawRoundedRect(QRectF(x(t)-3,4,6,12),1.5,1.5)
    def mousePressEvent(self,event):
        if event.button()!=Qt.MouseButton.LeftButton:return
        a,b=self.full;c,d=self.selected;x=event.position().x();cx=8+(c-a)/(b-a)*(self.width()-16);dx=8+(d-a)/(b-a)*(self.width()-16)
        self.drag=('left' if abs(x-cx)<=8 else 'right' if abs(x-dx)<=8 else 'pan');self.origin=(self.fraction(x),c,d)
    def mouseMoveEvent(self,event):
        if not self.drag:return
        a,b=self.full;f,c,d=self.origin;delta=(self.fraction(event.position().x())-f)*(b-a);minimum=(b-a)*.0001
        if self.drag=='left':c=max(a,min(d-minimum,c+delta))
        elif self.drag=='right':d=min(b,max(c+minimum,d+delta))
        else:
            delta=max(a-c,min(b-d,delta));c+=delta;d+=delta
        self.selected=(c,d);self.changed.emit(c,d);self.update()
    def mouseReleaseEvent(self,event):self.drag=None


def speed_key(value):
    v=finite_number(value)
    return f'{v:g}' if v is not None and v>=0 else None


def trial_identity(row):
    return str(row.get('recording_id') or row.get('source_file') or row.get('trial_id') or '')


def relative_trial_numbers(rows):
    # Assign a recording once, before response/unit/viewport filters. Every stimulus
    # in one recording refers to that recording's same relative trial number.
    conditions={}
    for row in rows:
        identity=trial_identity(row)
        if not identity:continue
        condition=(str(row.get('animal_id','')).strip().casefold(),speed_key(row.get('airspeed')))
        conditions.setdefault(condition,{})[identity]=row
    numbers={}
    def order(item):
        identity,row=item;seq=finite_number(row.get('sequence'))
        if seq is None:
            match=re.search(r'-(\d+)$',str(row.get('trial_id','')));seq=float(match[1]) if match else math.inf
        return (seq,str(row.get('recording_started','') or row.get('started_utc','')),identity)
    for records in conditions.values():
        for count,(identity,row) in enumerate(sorted(records.items(),key=order),1):numbers[identity]=count
    return numbers


def relative_trial_label(owner,row):
    number=getattr(owner,'relative_trials',{}).get(trial_identity(row))
    if number is None:number=relative_trial_numbers(getattr(owner,'project_rows',[]) or getattr(owner,'display_rows',[]) or [row]).get(trial_identity(row))
    return str(number) if number is not None else '?'


def valid_condition_colors(value):
    if not isinstance(value,dict):return {}
    out={}
    for speed,colors in value.items():
        key=speed_key(speed)
        if key is None or not isinstance(colors,dict):continue
        good={g:c.lower() for g,c in colors.items() if g in ('Control','Experiment') and isinstance(c,str) and re.fullmatch(r'#[0-9a-fA-F]{6}',c)}
        if good:out[key]=good
    return out


def condition_series(owner,group,speed=None):
    return (group,speed_key(speed)) if getattr(owner,'separate_airspeeds',False) else group


def condition_color(owner,group,speed=None):
    if isinstance(group,tuple):group,speed=group
    base=getattr(owner,'plot_colors',{}).get(str(group).lower(),{'Control':'#aa5959','Experiment':'#3274ac'}.get(group,'#777777'))
    key=speed_key(speed)
    if not getattr(owner,'separate_airspeeds',False) or key is None:return base
    custom=getattr(owner,'condition_colors',{}).get(key,{}).get(group)
    if custom:return custom
    return default_condition_color(base,key)


def default_condition_color(base,speed):
    # Speed determines the shade, not the filtered subset or Python's random hash.
    factors={'10':132,'20':100,'30':76,'40':115,'50':88}
    factor=factors.get(speed_key(speed))
    if factor is None:
        import hashlib
        factor=78+int(hashlib.sha256(str(speed_key(speed)).encode()).hexdigest()[:8],16)%51
    color=QColor(base)
    return (color.lighter(factor) if factor>=100 else color.darker(round(10000/factor))).name()


def condition_label(key):
    if isinstance(key,tuple):return f'{key[0]} · {key[1]} m/s' if key[1] is not None else f'{key[0]} · Air N/A'
    return str(key)


class ConditionLegend(QWidget):
    def __init__(self,owner):
        super().__init__();self.owner=owner;self.entries=[];self.setMinimumHeight(0);self.setSizePolicy(QSizePolicy.Policy.Expanding,QSizePolicy.Policy.Fixed);self.hide()
    def set_entries(self,keys):
        entries=list(dict.fromkeys(keys)) if getattr(self.owner,'separate_airspeeds',False) else []
        entries.sort(key=lambda k:(str(k[0]) if isinstance(k,tuple) else str(k),finite_number(k[1]) if isinstance(k,tuple) and finite_number(k[1]) is not None else -1))
        if entries!=self.entries:self.entries=entries;self.setToolTip('\n'.join(condition_label(k) for k in entries));self.reflow()
        self.setVisible(bool(entries) and not getattr(self,'suppressed',False));self.update()
    def positions(self):
        fm=self.fontMetrics();x=5;y=0;h=fm.height()+4
