    def init_interaction(self):
        self.setMouseTracking(True);self.hits=[];self.manual_axes={};self.plot_rect=QRectF();self.axis_limits={};self.auto_control=None;self.robust_auto=False;self.log_y=False;self.median_iqr=False;self.fit_all_active=False;self.outside=[];self.show_trials=True
