        robust=controls.robust.isChecked();log=controls.log.isChecked() and self.mode=='Trial Progression Plot';reset=robust!=self.robust_auto or log!=self.log_y
        self.robust_auto=robust;self.median_iqr=controls.median.isChecked();self.log_y=log;self.cached_plan=None
