    def outside_point(self,point,items,label,color):
        rect=self.plot_rect
        if rect.contains(point):return
        if not (math.isfinite(point.x()) and math.isfinite(point.y())):return
        edge='top' if point.y()<rect.top() else 'bottom' if point.y()>rect.bottom() else 'left' if point.x()<rect.left() else 'right'
        at=QPointF(max(rect.left()+5,min(rect.right()-5,point.x())),max(rect.top()+5,min(rect.bottom()-5,point.y())))
        self.outside.append((at,edge,items,label,QColor(color)))
