            for i in range(11):
                yy=y(i/10);p.setPen(QPen(QColor('#d0d0d0' if i%2==0 else '#e9e9e9'),.7));p.drawLine(QPointF(rect.left(),yy),QPointF(rect.right(),yy))
                if i%2==0 and rect.top()<=yy<=rect.bottom():p.setPen(QColor('#444444'));p.drawText(QRectF(20,yy-fh/2,rect.left()-28,fh),Qt.AlignmentFlag.AlignRight,f'{i/10:.1f}')
