                for i,value in enumerate(values):
                    path.lineTo(x(value),y(previous));previous=(i+1)/len(values);path.lineTo(x(value),y(previous))
                    members=[r for pt in points if condition_series(self.owner,pt['group'],pt['speed'])==group and pt['value']==value for r in pt['rows']]
                    self.register_point(QPointF(x(value),y(previous)),members,f'{self.owner.metric_label()}: {value:.3f}')
                path.lineTo(x(hi),y(1));pen=QPen(QColor(condition_color(self.owner,group)),1.7)
