from PyQt6.QtWidgets import QSplitterHandle,QScrollBar

class LinkedHandle(QSplitterHandle):
    def mouseMoveEvent(self,event):
        self.splitter().link_drag=bool(event.modifiers()&Qt.KeyboardModifier.ShiftModifier)
        super().mouseMoveEvent(event)
    def mouseReleaseEvent(self,event):
        super().mouseReleaseEvent(event);self.splitter().link_drag=False

class LinkedSplitter(QSplitter):
    def __init__(self,orientation):
        super().__init__(orientation);self.peers=[];self.link_drag=False;self.linking=False
        self.setHandleWidth(5);self.setChildrenCollapsible(False);self.setOpaqueResize(True)
        self.setStyleSheet('QSplitter::handle {background:transparent;border:none;}')
        self.splitterMoved.connect(self.link_position)
    def createHandle(self):return LinkedHandle(self.orientation(),self)
    def link_position(self,pos,index):
        if self.linking or not self.link_drag:return
        fraction=pos/max(1,self.height())
        for other in self.peers:
            if other is self or index>=other.count():continue
            other.linking=True
            try:other.moveSplitter(round(fraction*other.height()),index)
            finally:other.linking=False

