class WorkspaceSession(QObject):
    """Persist visual controls only; analysis parameters and raw data are unaffected."""
    def __init__(self,owner):
        super().__init__(owner);self.owner=owner;self.tables={};self.applying=False
        try:self.state=json.loads(CONFIG.read_text(encoding='utf-8-sig')).get('workspace_state',{})
        except (OSError,ValueError):self.state={}
        if not isinstance(self.state,dict):self.state={}
        self.state.setdefault('panels',{});self.state.setdefault('tables',{});self.layout_pending=set(owner.view_boards())
        owner.pages.currentChanged.connect(lambda *_:QTimer.singleShot(0,self.restore_current_layout))
        for page,board in owner.view_boards().items():
            for i,p in enumerate(board.panels):
                if hasattr(p,'stat_table'):self.register_table(f'{page}/{i}/statistics',p.stat_table)
            if hasattr(board,'csv_table'):self.register_table(f'{page}/raw',board.csv_table)
            if hasattr(board,'latency_table'):self.register_table(f'{page}/trials',board.latency_table)
        self.timer=QTimer(self);self.timer.timeout.connect(self.capture);self.timer.start(400)
        QTimer.singleShot(0,self.restore)
    def key(self,page,i,p):return f'{page}/{i}/{p.selector.currentText()}'
    def register_table(self,key,table):
        self.tables[key]=table
        table.model().modelReset.connect(lambda:self.queue_table(key))
        table.horizontalHeader().sectionResized.connect(lambda index,old,new:self.remember_column_width(key,index,new))
        table.destroyed.connect(lambda *_:self.tables.pop(key,None))
        self.queue_table(key)
    def remember_column_width(self,key,index,width):
        if self.applying or getattr(self.owner,'restoring_trial_columns',False):return
        table=self.tables.get(key)
        if table is None or table.isColumnHidden(index):return
        labels=self.table_columns(table)
        if 0<=index<len(labels) and 20<=width<=4000:
            saved=self.state['tables'].setdefault(key,{})
            saved.setdefault('widths',{})[labels[index]]=int(width)
    def queue_table(self,key):QTimer.singleShot(0,lambda:self.restore_table(key))
    def table_columns(self,t):
        model=t.model()
        return [str(model.headerData(i,Qt.Orientation.Horizontal) or i) for i in range(model.columnCount())]
    def capture_table(self,key):
        t=self.tables.get(key)
        if t is None:return
        labels=self.table_columns(t)
        if not labels:return
        widths=dict(self.state['tables'].get(key,{}).get('widths',{}));widths.update({s:t.columnWidth(i) for i,s in enumerate(labels) if not t.isColumnHidden(i)})
        self.state['tables'][key]={'widths':widths,
                                  'row_height':t.verticalHeader().defaultSectionSize(),
                                  'scroll_x':t.horizontalScrollBar().value(),'scroll_y':t.verticalScrollBar().value()}
    def restore_table(self,key):
        t=self.tables.get(key);saved=self.state['tables'].get(key)
        if t is None or not isinstance(saved,dict):return
        widths=saved.get('widths',{})
        blocked=t.horizontalHeader().blockSignals(True)
        for i,label in enumerate(self.table_columns(t)):
            width=widths.get(label)
            if isinstance(width,(int,float)) and 20<=width<=4000:t.setColumnWidth(i,int(width))
        t.horizontalHeader().blockSignals(blocked)
        height=saved.get('row_height')
        if isinstance(height,(int,float)) and 10<=height<=200:t.verticalHeader().setDefaultSectionSize(int(height))
        t.doItemsLayout();t.horizontalScrollBar().setValue(int(saved.get('scroll_x',0)));t.verticalScrollBar().setValue(int(saved.get('scroll_y',0)))
    def capture(self):
        if self.applying:return
        owner=self.owner
        self.state['geometry']=bytes(owner.saveGeometry()).hex()
        boards={}
        for page,board in owner.view_boards().items():
            boards[page]=self.state.get('boards',{}).get(page,{}) if page in self.layout_pending and page in self.state.get('boards',{}) else {'splitters':[bytes(s.saveState()).hex() for s in board.findChildren(QSplitter)],'follow':board.follow.isChecked(),'result_tab':board.result_tabs.currentIndex() if hasattr(board,'result_tabs') else 0}
            for i,p in enumerate(board.panels):
                saved=dict(auto=p.auto.isChecked(),bounds=list(p.canvas.bounds),custom_keys=p.custom_keys,custom_normalized=p.custom_normalized)
                if hasattr(p,'stat_plot'):
                    saved.update(stat_axes=p.stat_plot.manual_axes,global_axes=p.global_plot.manual_axes,offset=p.global_plot.offset,stat_scale=p.stat_plot.scale_snapshot(),show_trials=p.global_plot.show_trials)
                if hasattr(p,'review'):
                    r=p.review
                    # A temporarily empty review must retain a range waiting for the async load.
                    pending=getattr(r,'_pending_view_state',None)
                    saved['review']=pending if pending is not None and not r.canvas.data else dict(
                        manual_domain=r.canvas.manual_domain,full=r.full.isChecked(),detail=r.detail.isChecked(),
                        y_scale=r.y_scale.currentIndex(),confirmation=r.confirm.isChecked())
                self.state['panels'][self.key(page,i,p)]=saved
        self.state['boards']=boards
        for key in list(self.tables):self.capture_table(key)
    def restore_panels(self):
        self.applying=True
        try:
            for page,board in self.owner.view_boards().items():
                for i,p in enumerate(board.panels):
                    saved=self.state['panels'].get(self.key(page,i,p))
                    if not isinstance(saved,dict):continue
                    p.custom_keys=saved.get('custom_keys',p.custom_keys);p.custom_normalized=bool(saved.get('custom_normalized',p.custom_normalized))
                    if p.selector.currentText()=='Custom Overlay':p.change('Custom Overlay')
                    p.auto.setChecked(bool(saved.get('auto',True)));p.canvas.auto=p.auto.isChecked()
                    bounds=saved.get('bounds')
                    if isinstance(bounds,list) and len(bounds)==4 and all(finite_number(v) is not None for v in bounds) and bounds[1]>bounds[0] and bounds[3]>bounds[2]:
                        p.canvas.bounds=tuple(bounds)
                    if hasattr(p,'stat_plot'):
                        p.global_plot.show_trials=bool(saved.get('show_trials',True));p.stat_plot.show_trials=p.global_plot.show_trials;p.trials_toggle.setText('All' if p.global_plot.show_trials else 'Stats');p.stat_plot.scale_restore(saved.get('stat_scale',{}));p.scale_controls.restore(p.stat_plot)
                        for plot,key in ((p.stat_plot,'stat_axes'),(p.global_plot,'global_axes')):
                            axes=saved.get(key,{})
                            plot.manual_axes={k:tuple(v) for k,v in axes.items() if k in ('x','y') and isinstance(v,(list,tuple)) and len(v)==2 and all(finite_number(n) is not None for n in v) and v[1]>v[0]}
                            plot.update()
                        p.global_plot.offset=max(0,int(saved.get('offset',0)))
                    if hasattr(p,'review') and isinstance(saved.get('review'),dict):
                        p.review._pending_view_state=saved['review'];p.review.apply_pending_view()
                    p.sync_x_zoom();p.canvas.update()
                board.refresh_scale()
        finally:self.applying=False
    def restore_current_layout(self):
        from PyQt6.QtCore import QByteArray
        names=list(self.owner.view_boards());index=self.owner.pages.currentIndex()
        if not 0<=index<len(names):return
        name=names[index]
        if name not in self.layout_pending:return
        board=self.owner.view_boards()[name];saved=self.state.get('boards',{}).get(name,{})
        self.applying=True
        try:
            board.layout().activate()
            for splitter,value in zip(board.findChildren(QSplitter),saved.get('splitters',[])):
                splitter.restoreState(QByteArray.fromHex(value.encode()))
            board.follow.setChecked(saved.get('follow',board.follow.isChecked()))
            if hasattr(board,'result_tabs'):board.result_tabs.setCurrentIndex(saved.get('result_tab',1))
            self.layout_pending.remove(name)
        finally:self.applying=False
    def restore(self):
        from PyQt6.QtCore import QByteArray
        geometry=self.state.get('geometry')
        if geometry:self.owner.restoreGeometry(QByteArray.fromHex(geometry.encode()))
        self.restore_panels();self.restore_current_layout()
        for key in self.tables:self.restore_table(key)
    def save(self):
        self.capture()
        try:
            try:data=json.loads(CONFIG.read_text(encoding='utf-8-sig'))
            except (OSError,ValueError):data={}
            data['workspace_state']=self.state;atomic_json(CONFIG,data)
        except OSError as ex:self.owner.statusBar().showMessage('Could not save view layout: '+str(ex))



# R handoff: immutable, self-contained analysis snapshots.
def r_export_rows(rows,all_rows,include_cleaned=False):
    relative=relative_trial_numbers(all_rows);out=[]
    for original in rows:
        if not original.get('stimulus_index'):continue
        if is_test_deleted(original) and not include_cleaned:continue
        r=dict(original);r['day']=animal_parts(str(r.get('animal_id','')))[0]
        r['relative_trial']=relative.get(trial_identity(r))
        r['cleaned']=int(is_test_deleted(r))
        r['response']=1 if r.get('status')=='Response' else 0 if r.get('status')=='No response' else None
        out.append(r)
    return out

R_STARTER = r"""# Trial-level data; repeated trials are NOT independent animals.
# Startup profiles run before default packages are attached.
for (.pkg in c("utils", "stats", "graphics", "grDevices"))
  library(.pkg, character.only=TRUE)
rm(.pkg)
d <- read.csv('trials.csv', fileEncoding='UTF-8-BOM', check.names=FALSE,
              na.strings=c('', 'NA'), stringsAsFactors=FALSE)
for (k in intersect(c('corrected_latency_ms','raw_latency_ms','airspeed','day',
 'relative_trial','response','cleaned','peak_speed','post_path_length'), names(d)))
  d[[k]] <- suppressWarnings(as.numeric(d[[k]]))
d$animal_id <- factor(d$animal_id)
d$group <- factor(d$group)
d$airspeed_factor <- factor(d$airspeed)
valid <- subset(d, cleaned == 0 & status == 'Response' &
                is.finite(corrected_latency_ms) & corrected_latency_ms >= 0)
if (nrow(valid)) {
  animal_summary <- aggregate(corrected_latency_ms ~ animal_id + group + airspeed + unit,
                              data=valid, FUN=median)
  write.csv(animal_summary, 'animal_medians.csv', row.names=FALSE, na='')
  pdf('latency_summary.pdf', width=9, height=6)
  boxplot(corrected_latency_ms ~ interaction(group, airspeed), data=animal_summary,
          xlab='Group / airspeed (m/s)', ylab='Animal median corrected latency (ms)')
  dev.off()
}
write.csv(as.data.frame(table(d$status, useNA='ifany')), 'status_counts.csv', row.names=FALSE)
saveRDS(d, 'trials.rds')
writeLines(capture.output(sessionInfo()), 'R_session.txt')
# Optional model starting points after checking design, sample size, and residuals:
# lme4::glmer(response ~ group * airspeed_factor + factor(day) + (1|animal_id),
#             data=subset(d, cleaned == 0 & !is.na(response)), family=binomial)
# lme4::lmer(log(corrected_latency_ms) ~ group * airspeed_factor + factor(day) +
#            (1|animal_id), data=subset(valid, corrected_latency_ms > 0))
# No-response latency is missing, never zero. Already-moving trials are separate.
# P5-P95 display clipping is never applied to exported data.
message('Finished: trials.rds, status_counts.csv and, if available, animal_medians.csv / latency_summary.pdf')
"""

R_MODELS = '# Core mixed models. No packages are installed without user action.\ndir.create(\'models\', showWarnings=FALSE)\nrequired <- c(\'lme4\', \'emmeans\')\nmissing <- required[!vapply(required, requireNamespace, logical(1), quietly=TRUE)]\nif (length(missing)) {\n  instruction <- paste0(\'Install once in the R console, then source("analysis.R"):\\ninstall.packages(c(\',\n    paste(sprintf(\'"%s"\', missing), collapse=\', \'), \'))\')\n  writeLines(instruction, \'models/INSTALL_REQUIRED.txt\'); message(instruction)\n} else {\n  run_model <- function(label, outcome, binary=FALSE) {\n    warnings <- character()\n    tryCatch(withCallingHandlers({\n      z <- d[d$cleaned == 0 & d$status %in% c(\'Response\', \'No response\'), , drop=FALSE]\n      if (!binary) z <- z[z$status == \'Response\' & z$post_status == \'Complete\' |\n                           z$status == \'Response\' & outcome == \'corrected_latency_ms\', , drop=FALSE]\n      z <- z[!is.na(z$animal_id) & nzchar(as.character(z$animal_id)) &\n               is.finite(z$airspeed) & is.finite(z[[outcome]]), , drop=FALSE]\n      if (!binary) z <- z[z[[outcome]] > 0, , drop=FALSE]\n      z <- droplevels(z)\n      if (nrow(z) < 10 || nlevels(z$animal_id) < 3) stop(\'Fewer than 10 eligible trials or 3 animals.\')\n      if (length(unique(z$unit)) != 1) stop(\'Mixed units: select a single unit before analysis.\')\n      if (binary && length(unique(z[[outcome]])) < 2) stop(\'Response has no variation.\')\n      terms <- character()\n      if (nlevels(z$group) > 1 && nlevels(z$airspeed_factor) > 1) {\n        cells <- table(z$group, z$airspeed_factor)\n        if (all(cells > 0)) terms <- \'group * airspeed_factor\' else {\n          terms <- \'group + airspeed_factor\'\n          warnings <- c(warnings, \'Missing group x speed cells: additive model; interaction not estimable.\')\n        }\n      } else {\n        if (nlevels(z$group) > 1) terms <- c(terms, \'group\')\n        if (nlevels(z$airspeed_factor) > 1) terms <- c(terms, \'airspeed_factor\')\n      }\n      rhs <- if (length(terms)) paste(terms, collapse=\' + \') else \'1\'\n      fixed <- model.matrix(as.formula(paste(\'~\',rhs)), data=z)\n      if (qr(fixed)$rank < ncol(fixed)) stop(\'Confounded / rank-deficient design; review group, speed and day.\')\n      lhs <- if (binary) outcome else paste0(\'log(\',outcome,\')\')\n      formula <- as.formula(paste(lhs,\'~\',rhs,\'+ (1 | animal_id)\'))\n      fit <- if (binary) lme4::glmer(formula, data=z, family=binomial,\n                   control=lme4::glmerControl(optimizer=\'bobyqa\')) else lme4::lmer(formula,data=z,REML=TRUE)\n      prefix <- file.path(\'models\',label)\n      saveRDS(fit,paste0(prefix,\'.rds\'))\n      write.csv(z[c(\'recording_id\',\'stimulus_index\',\'animal_id\',\'group\',\'airspeed\',outcome)],\n                paste0(prefix,\'_included.csv\'),row.names=FALSE)\n      co <- as.data.frame(coef(summary(fit))); co$term <- rownames(co)\n      co$ratio <- exp(co$Estimate)\n      co$ratio_low <- exp(co$Estimate - 1.96*co[[\'Std. Error\']])\n      co$ratio_high <- exp(co$Estimate + 1.96*co[[\'Std. Error\']])\n      write.csv(co,paste0(prefix,\'_coefficients.csv\'),row.names=FALSE)\n      specs <- c(if(nlevels(z$group)>1)\'group\',if(nlevels(z$airspeed_factor)>1)\'airspeed_factor\')\n      emm <- emmeans::emmeans(fit, specs=if(length(specs)) specs else ~1)\n      write.csv(as.data.frame(confint(emm,type=\'response\')),paste0(prefix,\'_predictions.csv\'),row.names=FALSE)\n      write.csv(as.data.frame(summary(pairs(emm,adjust=\'tukey\'),type=\'response\',infer=c(TRUE,TRUE))),\n                paste0(prefix,\'_comparisons.csv\'),row.names=FALSE)\n      pdf(paste0(prefix,\'_diagnostics.pdf\'),width=9,height=5)\n      tryCatch({\n        par(mfrow=c(1,2));plot(fitted(fit),residuals(fit,type=\'pearson\'),\n           xlab=\'Fitted\',ylab=\'Pearson residual\');abline(h=0,lty=2)\n        if (!binary) {qqnorm(residuals(fit));qqline(residuals(fit))} else {\n          plot(jitter(z[[outcome]]),fitted(fit),xlab=\'Observed response (jitter)\',ylab=\'Fitted probability\')\n        }\n      },finally=dev.off())\n      if(binary && requireNamespace(\'DHARMa\',quietly=TRUE)) {\n        set.seed(20261029);sim <- DHARMa::simulateResiduals(fit,n=500)\n        pdf(paste0(prefix,\'_DHARMa.pdf\'));tryCatch(plot(sim),finally=dev.off())\n        writeLines(capture.output(DHARMa::testResiduals(sim)),paste0(prefix,\'_DHARMa.txt\'))\n      } else if(binary) warnings <- c(warnings,\'DHARMa absent: simulation-based binomial diagnostics not run. Optional: install.packages("DHARMa").\')\n      warnings <- c(warnings, fit@optinfo$conv$lme4$messages)\n      if(lme4::isSingular(fit)) warnings <- c(warnings,\'Singular fit: animal variance is on the boundary; review model.\')\n      writeLines(c(paste(\'Formula:\',deparse(formula)),paste(\'Trials:\',nrow(z),\'Animals:\',nlevels(z$animal_id)),\n        paste(\'Excluded from exported snapshot:\',nrow(d)-nrow(z)),\n        \'Animal random intercept; day and trial order NOT adjusted in this initial model.\',\n        \'Log-LMM response-scale predictions are geometric means, not arithmetic means.\',\n        \'Coefficient intervals are Wald approximations; LMM summaries do not supply p-values by default.\',\n        \'Review diagnostics, balance and warnings before inference. Small animal counts imply uncertain estimates.\',\n        capture.output(table(z$group,z$airspeed_factor)),capture.output(summary(fit)),\n        \'Warnings:\',if(length(warnings))unique(warnings) else \'None captured.\'),paste0(prefix,\'_report.txt\'))\n      message(label,\': finished; review models/\',label,\'_report.txt\')\n    },warning=function(w){warnings <<- c(warnings,conditionMessage(w));invokeRestart(\'muffleWarning\')}),\n    error=function(e){writeLines(c(conditionMessage(e),warnings),file.path(\'models\',paste0(label,\'_FAILED.txt\')));message(label,\': \',conditionMessage(e))})\n  }\n  run_model(\'response_probability\',\'response\',TRUE)\n  run_model(\'latency\',\'corrected_latency_ms\')\n  run_model(\'peak_speed\',\'peak_speed\')\n  run_model(\'movement_distance\',\'post_path_length\')\n}\nwriteLines(capture.output(sessionInfo()), \'R_session.txt\')\n'


RSTUDIO_VIEWER = '# Access results directly in RStudio. All values come from the fitted R models.\nmodel_results <- list()\nresult_tables <- list()\nfor (.name in c(\'response_probability\',\'latency\',\'peak_speed\',\'movement_distance\')) {\n .path <- file.path(\'models\',paste0(.name,\'.rds\'))\n if(file.exists(.path)) model_results[[.name]] <- readRDS(.path)\n result_tables[[.name]] <- list()\n for(.kind in c(\'predictions\',\'comparisons\',\'coefficients\',\'included\')) {\n  .path <- file.path(\'models\',paste0(.name,\'_\',.kind,\'.csv\'))\n  if(file.exists(.path)) result_tables[[.name]][[.kind]] <- read.csv(.path,check.names=FALSE)\n }\n}\nshow_result <- function(name=\'latency\') {\n if(!name %in% names(result_tables)) stop(\'Choose response_probability, latency, peak_speed or movement_distance.\')\n tab <- result_tables[[name]]$predictions\n if(is.null(tab) || !nrow(tab)) stop(\'No predictions available. Check the model report or INSTALL_REQUIRED.txt in models/.\')\n print(tab)\n lower <- grep(\'LCL|lower.CL\',names(tab),value=TRUE)[1]\n upper <- grep(\'UCL|upper.CL\',names(tab),value=TRUE)[1]\n value <- if(\'prob\' %in% names(tab)) \'prob\' else \'response\'\n scale <- if(value==\'prob\')100 else 1\n v <- tab[[value]]*scale;l <- tab[[lower]]*scale;h <- tab[[upper]]*scale\n labels <- apply(tab[,intersect(c(\'group\',\'airspeed_factor\'),names(tab)),drop=FALSE],1,paste,collapse=\' / \')\n unit <- unique(d$unit);unit <- if(length(unit)==1)unit else \'mixed units\'\n ylab <- switch(name,response_probability=\'Response (%)\',latency=\'Corrected latency (ms)\',peak_speed=paste0(\'Peak speed (\',unit,\'/s)\'),movement_distance=paste0(\'Distance (\',unit,\')\'))\n ylim <- range(c(l,h),finite=TRUE);if(value==\'prob\')ylim <- c(0,100)\n if(diff(ylim)==0)ylim <- ylim+c(-.5,.5)\n plot(seq_along(v),v,ylim=ylim,xlim=c(.5,length(v)+.5),xaxt=\'n\',pch=19,\n      xlab=\'Group / airspeed (m/s)\',ylab=ylab,main=paste(name,\'- prediction and 95% CI\'))\n axis(1,at=seq_along(v),labels=labels)\n arrows(seq_along(v),l,seq_along(v),h,angle=90,code=3,length=.06)\n invisible(tab)\n}\nmessage(\'Results available in RStudio: model_results, result_tables, d, valid, animal_summary.\')\nmessage(\'Plot: show_result("latency")  |  Table: View(result_tables$latency$comparisons)\')\nmessage(\'Model summary: summary(model_results$latency)  |  Full reports / diagnostic PDFs: Files > models\')\n'

R_HTTP_DASHBOARD = '# Portable HTML report; only standard R packages needed.\nhtml_escape <- function(x) {\n x <- as.character(x);x[is.na(x)] <- \'\'\n for(pair in list(c(\'&\',\'&amp;\'),c(\'<\',\'&lt;\'),c(\'>\',\'&gt;\'),c(\'"\',\'&quot;\'))) x <- gsub(pair[1],pair[2],x,fixed=TRUE)\n x\n}\nhtml_table <- function(x) {\n for(k in names(x)) if(is.numeric(x[[k]])) x[[k]] <- format(signif(x[[k]],4),trim=TRUE)\n paste0(\'<div class="table"><table><thead><tr>\',paste0(\'<th>\',html_escape(names(x)),\'</th>\',collapse=\'\'),\n \'</tr></thead><tbody>\',paste(vapply(seq_len(nrow(x)),function(i) paste0(\'<tr>\',paste0(\'<td>\',html_escape(unlist(x[i,,drop=FALSE],use.names=FALSE)),\'</td>\',collapse=\'\'),\'</tr>\'),character(1)),collapse=\'\'),\'</tbody></table></div>\')\n}\npalette <- if(file.exists(\'palette.csv\'))read.csv(\'palette.csv\',stringsAsFactors=FALSE) else data.frame()\nsections <- character()\nlabels <- c(response_probability=\'Response probability\',latency=\'Corrected latency\',peak_speed=\'Peak speed\',movement_distance=\'Post-onset distance\')\nunits <- c(response_probability=\'Response (%)\',latency=\'Latency (ms)\',peak_speed=\'Peak speed (mm/s)\',movement_distance=\'Distance (mm)\')\n# Use the exported measurement unit for kinematic outcomes.\nif(length(unique(d$unit))==1) {\n units[\'peak_speed\'] <- paste0(\'Peak speed (\',unique(d$unit),\'/s)\')\n units[\'movement_distance\'] <- paste0(\'Distance (\',unique(d$unit),\')\')\n}\ndir.create(\'report_assets\',showWarnings=FALSE)\nfor(key in names(labels)) {\n prefix <- file.path(\'models\',key);body <- character()\n prediction <- paste0(prefix,\'_predictions.csv\');report <- paste0(prefix,\'_report.txt\')\n if(file.exists(prediction)) {\n  p <- read.csv(prediction,check.names=FALSE)\n  low <- grep(\'LCL|lower.CL\',names(p),value=TRUE)[1];high <- grep(\'UCL|upper.CL\',names(p),value=TRUE)[1]\n  value <- if(\'prob\' %in% names(p)) \'prob\' else \'response\'\n  if(!is.na(low) && !is.na(high) && value %in% names(p)) {\n   scale <- if(key==\'response_probability\') 100 else 1\n   v <- p[[value]]*scale;l <- p[[low]]*scale;h <- p[[high]]*scale\n   tick <- apply(p[,intersect(c(\'group\',\'airspeed_factor\'),names(p)),drop=FALSE],1,paste,collapse=\' / \')\n   point_colors <- vapply(seq_len(nrow(p)),function(i) {\n     group <- if(\'group\' %in% names(p))as.character(p$group[i]) else if(length(unique(d$group))==1)as.character(unique(d$group)) else \'All groups\'\n     speed <- if(\'airspeed_factor\' %in% names(p))as.character(p$airspeed_factor[i]) else \'\'\n     found <- if(nrow(palette))which(palette$group==group & as.character(palette$airspeed)==speed) else integer()\n     if(length(found))palette$color[found[1]] else if(group==\'Experiment\')\'#3274ac\' else \'#aa5959\'\n   },character(1))\n   imagefile <- paste0(\'report_assets/\',key,\'.png\')\n   png(imagefile,width=1000,height=550,res=130)\n   tryCatch({\n    par(mar=c(5,5,2,1));bounds <- range(c(l,h),finite=TRUE)\n    if(key==\'response_probability\') bounds <- c(0,100)\n    if(diff(bounds)==0) bounds <- bounds+c(-.5,.5)\n    plot(seq_along(v),v,ylim=bounds,xlim=c(.5,length(v)+.5),xaxt=\'n\',pch=19,col=point_colors,\n         xlab=\'Group / airspeed (m/s)\',ylab=units[key],cex=1.2)\n    axis(1,at=seq_along(v),labels=tick);arrows(seq_along(v),l,seq_along(v),h,angle=90,code=3,length=.06,col=point_colors)\n   },finally=dev.off())\n   body <- c(body,\'<p class="legend">\',paste(vapply(seq_along(tick),function(i)paste0(\'<span class="legend-item"><i style="background:\',html_escape(point_colors[i]),\'"></i>\',html_escape(tick[i]),\' m/s</span>\'),character(1)),collapse=\'\'),\' · dots = model prediction; bars = 95% CI</p>\')\n   body <- c(body,paste0(\'<img src="\',imagefile,\'" alt="\',labels[key],\' predictions and 95% CI">\'))\n  }\n  body <- c(body,\'<h3>Model predictions · 95% CI</h3>\',html_table(p))\n }\n comparison <- paste0(prefix,\'_comparisons.csv\')\n if(file.exists(comparison)) body <- c(body,\'<details><summary>Pairwise comparisons · Tukey adjustment within this outcome</summary>\',html_table(read.csv(comparison,check.names=FALSE)),\'</details>\')\n if(file.exists(report)) body <- c(body,\'<details><summary>Model formula, sample size and warnings</summary><pre>\',html_escape(paste(readLines(report,warn=FALSE),collapse=\'\\n\')),\'</pre></details>\')\n failure <- paste0(prefix,\'_FAILED.txt\')\n if(file.exists(failure)) body <- c(body,\'<p class="warning">Model incomplete</p><pre>\',html_escape(paste(readLines(failure,warn=FALSE),collapse=\'\\n\')),\'</pre>\')\n if(!length(body)) body <- \'<p class="warning">Model output unavailable. Check models/INSTALL_REQUIRED.txt for package installation instructions.</p>\'\n diag <- paste0(prefix,\'_diagnostics.pdf\')\n if(file.exists(diag)) body <- c(body,paste0(\'<p><a href="\',diag,\'">Residual diagnostic plots (PDF)</a></p>\'))\n dh <- paste0(prefix,\'_DHARMa.txt\')\n if(file.exists(dh)) body <- c(body,\'<details open><summary>DHARMa diagnostic tests</summary><pre>\',html_escape(paste(readLines(dh,warn=FALSE),collapse=\'\\n\')),\'</pre></details>\')\n sections <- c(sections,paste0(\'<section><h2>\',labels[key],\'</h2>\',paste(body,collapse=\'\\n\'),\'</section>\'))\n}\n# Descriptive latency heatmap: display clipping only; source values remain intact.\ntryCatch({\n z <- d[d$cleaned==0 & d$status==\'Response\' & is.finite(d$corrected_latency_ms) &\n          is.finite(d$relative_trial) & d$relative_trial>=1,,drop=FALSE]\n if(nrow(z)) {\n  row_id <- paste(z$animal_id,z$airspeed,sep=\' / \');ids <- unique(row_id)\n  x <- as.integer(z$relative_trial);m <- matrix(NA_real_,nrow=length(ids),ncol=max(x))\n  # Multiple stimulus rows at the same relative recording position: median per cell.\n  for(i in seq_along(ids)) for(j in unique(x[row_id==ids[i]]))\n   m[i,j] <- median(z$corrected_latency_ms[row_id==ids[i] & x==j],na.rm=TRUE)\n  bounds <- quantile(m,c(.05,.95),na.rm=TRUE);if(diff(bounds)==0)bounds <- bounds+c(-.5,.5)\n  colors <- hcl.colors(100,\'Viridis\');mapped <- pmax(1,pmin(100,1+floor((m-bounds[1])/diff(bounds)*99)))\n  png(\'report_assets/latency_heatmap.png\',width=1200,height=max(430,160+length(ids)*23),res=130)\n  tryCatch({\n   par(mar=c(5,9,2,7));plot(NA,xlim=c(.5,ncol(m)+.5),ylim=c(.5,nrow(m)+.5),\n      xaxt=\'n\',yaxt=\'n\',xlab=\'Relative trial within animal × airspeed\',ylab=\'\',bty=\'n\')\n   axis(1,at=seq_len(ncol(m)));axis(2,at=seq_len(nrow(m)),labels=rev(ids),las=2,cex.axis=.72)\n   for(i in seq_len(nrow(m)))for(j in seq_len(ncol(m))) {\n    y <- nrow(m)-i+1;v <- m[i,j]\n    rect(j-.5,y-.5,j+.5,y+.5,col=if(is.na(v))\'#dedede\' else if(v<bounds[1] || v>bounds[2])colors[100] else colors[mapped[i,j]],border=\'white\')\n    if(!is.na(v) && (v<bounds[1] || v>bounds[2]))text(j,y,\'×\',col=\'white\',cex=.9)\n   }\n   legend(\'topright\',inset=c(-.18,0),xpd=TRUE,bty=\'n\',cex=.75,\n     legend=c(sprintf(\'P5: %.1f ms\',bounds[1]),sprintf(\'P95: %.1f ms\',bounds[2]),\'Missing\',\'× Outside P5–P95\'),\n     fill=c(colors[1],colors[100],\'#dedede\',NA))\n  },finally=dev.off())\n  sections <- c(sections,paste0(\'<section class="wide"><h2>Trial latency heatmap</h2><p>P5–P95 pseudocolor; both tails use the deepest color and ×. Grey = missing / no valid latency. Multiple stimuli in one recording position are summarized by median for display only.</p><img src="report_assets/latency_heatmap.png" alt="Latency heatmap"></section>\'))\n }\n},error=function(e) message(\'Heatmap unavailable: \',conditionMessage(e)))\n\nstatus <- as.data.frame(table(d$status,useNA=\'ifany\'));names(status) <- c(\'Status\',\'Trials\')\nbalance <- as.data.frame(table(d$day,d$airspeed));names(balance) <- c(\'Day\',\'Airspeed\',\'Trials\');balance <- balance[balance$Trials>0,]\nreport_html <- paste0(\'<!doctype html><html><head><meta charset="utf-8"><title>TreadScope statistical results</title><style>\',\n \'body{font:15px Segoe UI,Arial,sans-serif;color:#263342;background:#f2f4f6;margin:24px auto;max-width:1280px;padding:0 20px}h1{margin-bottom:8px}section,.overview{background:white;padding:22px;border:1px solid #dce1e5;border-radius:8px;margin:16px 0} .grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(460px,1fr));gap:16px}section{margin:0;min-width:0}img{width:100%;height:auto}.wide{grid-column:1/-1}.legend{display:flex;flex-wrap:wrap;gap:12px;font-size:14px}.legend-item{display:inline-flex;align-items:center;gap:6px}.legend i{width:22px;height:4px;display:inline-block}table{border-collapse:collapse;width:100%;font-size:13px}td,th{padding:8px;text-align:left;border-bottom:1px solid #e4e7eb}.table{overflow-x:auto}summary{cursor:pointer;margin:16px 0;font-weight:600}pre{white-space:pre-wrap;font:12px Consolas,monospace;overflow-wrap:anywhere}.warning{color:#9c4d13}a{color:#2465a5}</style></head><body>\',\n \'<h1>TreadScope · Statistical results</h1><p>\',format(Sys.time()),\' · \',nrow(d),\' exported trials · \',length(unique(d$animal_id)),\' animals</p>\',\n \'<div class="overview"><strong>Interpretation</strong><p>Animal random-intercept models. Day and trial order are not adjusted. Predictions for continuous outcomes are geometric means; response probabilities are conditional on zero animal random effect. Confidence intervals and comparisons currently use asymptotic inference. Review balance and residual diagnostics before drawing conclusions. Positive log models exclude zero values. No P5–P95 clipping is applied to statistical data. Four outcomes have no across-outcome multiplicity adjustment.</p>\',\n \'<details><summary>Response status and day / airspeed balance</summary>\',html_table(status),html_table(balance),\'</details></div><div class="grid">\',paste(sections,collapse=\'\\n\'),\n \'</div><p>Full fitted models, included trial lists and CSV results: models/</p></body></html>\')\nwriteLines(enc2utf8(report_html),\'results.pending.html\',useBytes=TRUE)\nif(file.exists(\'results.html\'))unlink(\'results.html\')\nif(!file.rename(\'results.pending.html\',\'results.html\'))stop(\'Could not publish dashboard file\')\nmessage(\'Visual report saved: \',normalizePath(\'results.html\'))\n'
R_HTTP_SERVER = "import functools,http.server,os,sys,threading,time,webbrowser\nfrom pathlib import Path\nroot=Path(__file__).resolve().parent\nclass Handler(http.server.SimpleHTTPRequestHandler):\n    def log_message(self,*args):pass\n    def end_headers(self):\n        self.send_header('Cache-Control','no-store');super().end_headers()\n    def list_directory(self,path):self.send_error(403);return None\nserver=http.server.ThreadingHTTPServer(('127.0.0.1',0),functools.partial(Handler,directory=str(root)))\nserver.daemon_threads=True\nurl=f'http://127.0.0.1:{server.server_port}/index.html'\n(root/'dashboard_url.txt').write_text(url,encoding='utf-8')\ndef watch_parent():\n    while True:\n        time.sleep(3)\n        if os.name=='nt':\n            import ctypes\n            api=ctypes.windll.kernel32;api.OpenProcess.restype=ctypes.c_void_p\n            api.WaitForSingleObject.argtypes=[ctypes.c_void_p,ctypes.c_ulong];api.CloseHandle.argtypes=[ctypes.c_void_p]\n            handle=api.OpenProcess(0x100000,False,int(sys.argv[1]))\n            alive=bool(handle) and api.WaitForSingleObject(handle,0)==258\n            if handle:api.CloseHandle(handle)\n        else:alive=os.getppid()==int(sys.argv[1])\n        if not alive:server.shutdown();return\nthreading.Thread(target=watch_parent,daemon=True).start()\nwebbrowser.open(url)\nserver.serve_forever()\n"
R_HTTP_WAIT = '<!doctype html><html><head><meta charset="utf-8"><title>TreadScope Results</title><style>body{font:16px Segoe UI,Arial;padding:40px;color:#263342}p{max-width:750px}</style></head><body><h1>Waiting for R results…</h1><p>RStudio is opening this snapshot. The dashboard will update automatically when analysis finishes. If automatic analysis is disabled, run source("analysis.R") in RStudio. Check its Console for missing packages or errors.</p><script>setInterval(async()=>{try{const r=await fetch(\'results.html\',{cache:\'no-store\'});if(r.ok)location.replace(\'results.html\')}catch(e){}},2000)</script></body></html>'

def write_r_bundle(folder,rows,metadata,autorun=True):
    folder=Path(folder);folder.mkdir(parents=True,exist_ok=False)
    try:
        write_summary(folder/'trials.csv',rows)
        (folder/'manifest.json').write_text(json.dumps(metadata,ensure_ascii=False,indent=2,default=str),encoding='utf-8')
        (folder/'analysis.R').write_text(R_STARTER+'\nsource("models.R", encoding="UTF-8")\nsource("view_results.R", encoding="UTF-8")\nsource("dashboard.R", encoding="UTF-8")\n',encoding='utf-8')
        (folder/'models.R').write_text(R_MODELS,encoding='utf-8')
        (folder/'view_results.R').write_text(RSTUDIO_VIEWER,encoding='utf-8')
        (folder/'dashboard.R').write_text(R_HTTP_DASHBOARD,encoding='utf-8')
        (folder/'serve_dashboard.py').write_text(R_HTTP_SERVER,encoding='utf-8')
        (folder/'index.html').write_text(R_HTTP_WAIT,encoding='utf-8')
        (folder/'TreadScope.Rproj').write_text('Version: 1.0\nRestoreWorkspace: No\nSaveWorkspace: No\nAlwaysSaveHistory: No\nEncoding: UTF-8\n',encoding='utf-8')
        if autorun:(folder/'.Rprofile').write_text('tryCatch(source("analysis.R", encoding="UTF-8"), error=function(e) message("Analysis failed: ", conditionMessage(e)))\n',encoding='utf-8')
        fields=list(dict.fromkeys(k for row in rows for k in row))
        (folder/'README.txt').write_text('TreadScope R snapshot\nOne row per recording_id + stimulus_index.\nOpen TreadScope.Rproj in RStudio, or run Rscript --vanilla analysis.R in this directory.\nThe project startup runs analysis.R when auto-run is enabled.\nAnalysis uses animal medians for the initial descriptive plot; four mixed models run when lme4 and emmeans are installed; see models/ reports and diagnostics.\nNo packages are installed automatically. Source recordings are unchanged.\nMissing numeric values are empty CSV cells. day is parsed from the Animal ID; it is not a calendar date.\nRelative trials follow the original animal x airspeed ordering, including excluded positions.\nCleaning records, if exported, remain flagged and are excluded from the starter statistics.\nAll original row fields are preserved; units are in unit, latency/time-window fields ending _ms are milliseconds, _s are seconds, airspeed is m/s.\nFields:\n'+ '\n'.join(fields),encoding='utf-8')
    except Exception:
        import shutil
        shutil.rmtree(folder,ignore_errors=True);raise
    return folder

R_ICON_BASE64 = ''

class ProjectWindow(Window):
    def __init__(self,engine=None):
        self.project_ready=False;self.project_worker=None;self.project_pending=False;self.project_rows=[];self.display_rows=[];self.registry=[];self.focus_result=None;self.accepting_record=False;self.project_queued=None;self.project_payload=None;self.project_failure=None
        try:self.registry=json.loads(CONFIG.read_text(encoding='utf-8-sig')).get('projects',[])
        except (OSError,ValueError):pass
        super().__init__(engine)
        for editor in self.setting_editors:
            combo=QComboBox();editor.layout().insertRow(0,'Project',combo);editor.project_combo=combo
            combo.currentTextChanged.connect(self.select_project)
        self.build_project_analysis()
        self.build_r_bridge()
        self.destroyed.connect(lambda *_:[p.terminate() for p in getattr(self,'http_dashboard_processes',[]) if p.poll() is None])
        self.project_ready=True;self.refresh_projects()
        self.build_replay_latency()
        self.file_label.stepped.connect(self.navigate_replay_trial)
        self.build_replay_reviews()
        self.load_default_views()
        self.apply_default_views()
        self.auto_stop_timer=QTimer(self);self.auto_stop_timer.setTimerType(Qt.TimerType.PreciseTimer)
        self.auto_stop_timer.timeout.connect(self.poll_auto_stop);self.auto_stop_timer.start(10)
        self.analysis_board.result_tabs.setCurrentIndex(1)
        if self.metadata.get('auto_trial_id'):
            try:self.metadata['trial_id']=self.next_trial()
            except ValueError:self.metadata['trial_id']=''
        self.refresh_trial_editors()
        self.pulse_ms.valueChanged.connect(self.invalidate_trial_settings)
        self.recover_pending_captures()
        self.view_save_timer=QTimer(self);self.view_save_timer.setSingleShot(True);self.view_save_timer.timeout.connect(self.persist_view_choices)
        for name,board in self.view_boards().items():
            for i,panel in enumerate(board.panels):panel.selector.currentTextChanged.connect(lambda mode,n=name,j=i:self.remember_view_choice(n,j,mode))
        self.view_defaults={name:[panel.selector.currentText() for panel in board.panels] for name,board in self.view_boards().items()}
        try:self.last_recording_path=json.loads(CONFIG.read_text(encoding='utf-8-sig')).get('last_recording','')
        except (OSError,ValueError):self.last_recording_path=''
        self.restore_recording_pending=True;self.restoring_recording=False
        self.pages.currentChanged.connect(self.restore_last_recording)
        QTimer.singleShot(0,lambda:self.restore_last_recording(self.pages.currentIndex()))
        self.view_session=WorkspaceSession(self)
        self.explorer=ExplorerPage(self);self.pages.insertTab(3,self.explorer,'Explorer')
        self.pages.currentChanged.connect(self.explorer_entered)
    def explorer_entered(self,index):
        if index!=3:return
        if getattr(self,'loaded_project_context',None)!=self.project_context():self.refresh_project(False)
        else:self.explorer.reload()
    def database_root(self):
        name=self.analysis_project.currentText() or self.metadata.get('project','')
        if not name:raise ValueError('Create or select a project first.')
        return (Path(self.output['root']).expanduser()/valid_project(name)).resolve()
    def load_database_preferences(self):
        if not hasattr(self,'project_root_loaded'):return
        with ProjectStore(self.project_root_loaded) as store:
            self.database_sort=store.preference('sort_order',DEFAULT_DB_SORT)
            self.database_columns=store.preference('column_order',[k for k,_ in DATABASE_COLUMNS]);self.database_hidden=store.preference('hidden_columns',[])
    def database_labels_changed(self):
        self._trial_draft_key=None
        for record in (self.replay_record,self.analysis_record):
            if record:apply_database_metadata(record)
        self.focus_result=None;self.refresh_project(False)
    def open_database(self):
        if self.trial_move_busy():return
        try:
            dialog=DatabaseDialog(self,self.database_root());dialog.exec();self.load_database_preferences();self.database_labels_changed()
        except Exception as ex:QMessageBox.warning(self,'Database',str(ex))
    def edit_selected_metadata(self):
        if self.trial_move_busy():return
        indices=self.analysis_board.latency_table.selectionModel().selectedRows()
        ids=list(dict.fromkeys(self.display_rows[i.row()]['recording_id'] for i in indices if i.row()<len(self.display_rows)))
        if not ids:return
        try:
            if MetadataEditDialog(self,self.project_root_loaded,ids).exec()==QDialog.DialogCode.Accepted:self.database_labels_changed()
        except Exception as ex:QMessageBox.warning(self,'Edit Information',str(ex))
    def database_preferences(self):
        if self.trial_move_busy():return
        try:
            if DatabaseViewDialog(self,self.database_root()).exec()==QDialog.DialogCode.Accepted:
                self.load_database_preferences();self.render_project_rows()
        except Exception as ex:QMessageBox.warning(self,'View Preferences',str(ex))
    def restore_last_recording(self,index):
        if index not in (1,2) or not self.restore_recording_pending:return
        if self.replay_record is not None:self.restore_recording_pending=False;return
        if self.engine.active or getattr(self,'load_pending',False):return
        self.restore_recording_pending=False
        path=self.last_recording_path
        if not path:return
        if not Path(path).is_file():
            self.statusBar().showMessage('Last recording is unavailable. Use Open Recording to select a file.',15000);return
        self.restoring_recording=True;self.load_path(path)
    def persist_last_recording(self,record):
        path=getattr(record,'archive_path',None) or getattr(record,'metadata_path',None) or getattr(record,'source_path',None)
        if not path:return
        self.last_recording_path=str(Path(path).resolve())
        try:
            try:data=json.loads(CONFIG.read_text(encoding='utf-8-sig'))
            except (OSError,ValueError):data={}
            data['last_recording']=self.last_recording_path;CONFIG.parent.mkdir(parents=True,exist_ok=True);atomic_json(CONFIG,data)
        except OSError as ex:self.statusBar().showMessage('Could not remember recording: '+str(ex))
    def remember_view_choice(self,name,index,mode):
        self.view_defaults[name][index]=mode;self.view_save_timer.start(300)

    def build_r_bridge(self):
        try:self.r_settings=json.loads(CONFIG.read_text(encoding='utf-8-sig')).get('r_bridge',{})
        except (OSError,ValueError):self.r_settings={}
        if not isinstance(self.r_settings,dict):self.r_settings={}
        page=self.pages.widget(2);layout=page.layout();top=QHBoxLayout();left=QVBoxLayout()
        # Wrap only the existing top controls; the plot board keeps its full width.
        while layout.count() and layout.itemAt(0).widget() is not self.analysis_board:
            left.addItem(layout.takeAt(0))
        top.addLayout(left,1);right=QVBoxLayout();self.r_button=QPushButton();icon_pixmap=QPixmap();icon_pixmap.loadFromData(base64.b64decode(R_ICON_BASE64));self.r_button.setIcon(QIcon(icon_pixmap));self.r_button.setIconSize(QSize(52,36))
        self.r_button.setFixedSize(104,64);self.r_button.setStyleSheet('QPushButton { color: #2465a5; font-size: 36px; font-weight: bold; }')
        self.r_button.setToolTip('Export trial dataset and open RStudio');self.r_button.clicked.connect(self.export_to_r)
        settings=QPushButton('R Settings');settings.setFixedWidth(104);settings.clicked.connect(self.edit_r_settings)
        right.addWidget(self.r_button);right.addWidget(settings);right.addStretch();top.addLayout(right);layout.insertLayout(0,top)
    def edit_r_settings(self):
        dialog=QDialog(self);dialog.setWindowTitle('R Integration Settings');form=QFormLayout(dialog)
        form.addRow('Open with',QLabel('RStudio'))
        editors={}
        for key,label in [('executable','RStudio executable'),('directory','Export directory')]:
            edit=QLineEdit(str(self.r_settings.get(key,'')));editors[key]=edit;row=QHBoxLayout();row.addWidget(edit);button=QPushButton('Browse');row.addWidget(button)
            def browse(checked=False,k=key,e=edit):
                value=QFileDialog.getExistingDirectory(dialog,'Export directory',e.text()) if k=='directory' else QFileDialog.getOpenFileName(dialog,'Select executable',e.text(),'Programs (*.exe);;All files (*)')[0]
                if value:e.setText(value)
            button.clicked.connect(browse);form.addRow(label,row)
        auto=QCheckBox('Run analysis automatically in RStudio');auto.setChecked(self.r_settings.get('autorun',True));form.addRow(auto)
        dashboard=QCheckBox('Open local HTTP dashboard alongside RStudio');dashboard.setChecked(self.r_settings.get('http_dashboard',True));form.addRow(dashboard)
        cleaned=QCheckBox('Include cleaned trials (flagged; excluded from starter statistics)');cleaned.setChecked(self.r_settings.get('cleaned',False));form.addRow(cleaned)
        note=QLabel('Exports the current Analysis filters. Blank executable: detect installed RStudio.\nEach export creates a new snapshot. Advanced models can be added to analysis.R.');note.setWordWrap(True);form.addRow(note)
        buttons=QDialogButtonBox(QDialogButtonBox.StandardButton.Save|QDialogButtonBox.StandardButton.Cancel);buttons.accepted.connect(dialog.accept);buttons.rejected.connect(dialog.reject);form.addRow(buttons)
        if dialog.exec()!=QDialog.DialogCode.Accepted:return
