        if not record or any(finite_number(row.get(k)) is None for k in keys) or row.get('status') in ('Needs recalculation','Not calculated','Unit mismatch'):
            self.clear_replay_review('Click Calculate Latencies for this recording.');return
        key=(id(record),float(row['window_ms']))
