        for editor in self.setting_editors:
            c=editor.project_combo;c.blockSignals(True);c.clear();c.addItems(names);c.setCurrentIndex(c.findText(self.metadata.get('project','')));c.blockSignals(False)
        c=self.analysis_project;old=c.currentText() or self.metadata.get('project','');c.blockSignals(True);c.clear();c.addItems(names);c.setCurrentIndex(c.findText(old));c.blockSignals(False)
