    def new_trial(self):
        if self.engine.active or self.engine.pending_capture:return
        self.pages.setCurrentIndex(0)
        self.statusBar().showMessage('Ready. Start recording, then complete Setting after stopping.')
    def save_trial_settings(self):
        e=self.engine
        if e.active or not e.pending_capture:return False
        try:
            project=valid_project(self.metadata.get('project',''))
            if project not in self.project_names():raise ValueError('Create the project in Settings > Trial Information first.')
            if self.metadata.get('treatment') not in ('Experiment','Control'):raise ValueError('Choose Experiment or Control.')
            trial_prefix(self.metadata)  # Validate Animal ID and finite airspeed.
            if not self.metadata.get('auto_trial_id') and not str(self.metadata.get('trial_id','')).strip():
                raise ValueError('Enter a Trial ID or enable automatic generation.')
            sequence=int(e.meta.get('pending_sequence',self.sequence))
            final,trial=e.save_pending(self.next_output or self.output,self.metadata,sequence)
        except Exception as ex:
            QMessageBox.warning(self,'Recording Not Saved',str(ex));return False
        index_warning=''
        try:
            with ProjectStore(final.parents[0] if not project_for_path(final) else project_for_path(final)) as store:
                with store.db:store.import_record(final)
        except Exception as ex:index_warning=' (saved; database indexing needs Refresh: '+str(ex)+')'
        self.metadata=trial;self.sequence=max(self.sequence,sequence+1);self.next_output=None
        self._trial_draft_key=None;self.trial_settings_saved=False;self.saved_trial_signature=None
        self.save_config();self.refresh_trial_editors();self.update_buttons();self.tick()
        self.statusBar().showMessage('Saved: '+str(final)+index_warning)
        self.recover_pending_captures()
        return True
    def delete_pending_capture(self):
        if self.engine.active or not self.engine.pending_capture:return False
        try:self.engine.delete_pending()
        except Exception as ex:QMessageBox.warning(self,'Delete Failed',str(ex));return False
        self._trial_draft_key=None
        self.live_cache_key=None;self.capture_board.set_record(Recording().build_series())
        self.refresh_trial_editors();self.update_buttons();self.tick()
        self.statusBar().showMessage('Unsaved recording permanently deleted. Ready for next recording.')
        self.recover_pending_captures()
        return True
    def show_pending_capture(self):
        if self.engine.active or not self.engine.pending_capture:return
        if self.metadata.get('auto_trial_id'):
            try:self.metadata['trial_id']=self.next_trial()
            except (ValueError,OSError):self.metadata['trial_id']=''
        self.pages.setCurrentIndex(0);self.capture_board.panels[0].selector.setCurrentText('Setting')
        self.refresh_trial_editors();self.statusBar().showMessage('Save or delete this recording before starting the next.')
    def recover_pending_captures(self):
        if self.engine.active or self.engine.pending_capture:return
        root=CONFIG.parent/'pending-recordings'
        if not root.exists():return
        for work in sorted(root.iterdir()):
            if not work.is_dir() or not re.fullmatch(r'[0-9a-f]{32}',work.name):continue
            try:
                meta=json.loads((work/'metadata.json').read_text(encoding='utf-8-sig'))
                if meta.get('status')=='saved':continue
                dest=meta.get('save_destination')
                if dest and Path(dest).is_file() and recording_metadata(dest).get('recording_id')==meta.get('recording_id'):
                    continue  # Save was published before an interrupted staging cleanup.
                lease=pending_lease(work)
                if lease is None:continue
                try:self.engine.recover_pending(work)
                except Exception:lease.close();raise
                self.engine.pending_lease=lease
                self.metadata.update(meta.get('draft_trial',{}));self.next_output=meta.get('pending_output') or self.next_output
                self._trial_draft_key=None;self.show_pending_capture();self.update_buttons();self.tick()
                self.statusBar().showMessage('Recovered unsaved recording. Review Setting, then Save or Delete.')
                return
            except Exception as ex:
                QMessageBox.warning(self,'Pending Recording Recovery',str(work)+'\n'+str(ex)+'\nFiles have been retained.')
                return
