        for i,r in enumerate(rows):combo.addItem('Stimulus '+str(r.get('stimulus_index',i+1)))
        combo.setCurrentIndex(min(max(0,old),len(rows)-1));combo.blockSignals(False);self.show_replay_latency();self.replay_latency_export.setEnabled(bool(rows))
