    def sync_replay_latency(self):
        if not self.replay_record or not hasattr(self,'project_root_loaded'):return
        path=Path(getattr(self.replay_record,'archive_path',None) or getattr(self.replay_record,'metadata_path',None) or self.replay_record.source_path).resolve()
        rows=[r for r in self.project_rows if r.get('stimulus_index') and (self.project_root_loaded/r['source_file']).resolve()==path]
        if rows and all(r.get('unit')==self.replay_record.unit and r.get('status')!='Unit mismatch' for r in rows):self.set_replay_latency_rows(rows)
