        self.latency_worker.completed.connect(lambda rows:setattr(self,'replay_latency_payload',rows));self.latency_worker.failed.connect(lambda msg:setattr(self,'replay_latency_error',msg));self.latency_worker.finished.connect(self.replay_latency_finished)
