        if getattr(self,'project_ready',False):
            if self.engine.pending_capture:self.start_btn.setEnabled(False);self.test_btn.setEnabled(False)
            self.update_trial_delete_buttons()
            if hasattr(self,'replay_latency_calc'):
                busy=self.trial_move_busy();self.replay_latency_calc.setEnabled(bool(self.replay_record) and not busy);self.replay_latency_settings.setEnabled(not busy);self.replay_latency_export.setEnabled(bool(self.replay_latency_rows) and not busy)
                self.latency_settings.setEnabled(not busy);self.latency_button.setEnabled(not busy)
        if getattr(self,'project_ready',False) and self.project_pending:
            for b in (self.replay_delete,self.analysis_delete,self.test_btn,self.start_btn,self.settings_button):b.setEnabled(False)
