                destination=root/'Delete'/path.name;destination.parent.mkdir(exist_ok=True)
                if destination.exists():destination=destination.with_name(destination.stem+'-'+uuid.uuid4().hex[:8]+'.zip')
                shutil.move(str(path),str(destination))
