        self.file_label.setText('Choose a recording ZIP, Raw CSV or Metadata JSON');self.file_label.setToolTip('');self.replay_time=0;self.progress.setValue(0);self.time_label.setText('0.000 / 0.000 s');self.analysis_info.setText('Open a recording to inspect an interval and compare stimulus phases.');self.analysis_board.csv_info.setText('Open a recording to preview its raw CSV.');self.replay_notice.setText('Moved to '+str(destination));self.invalidate_replay_latency();self.update_buttons()
        self.refresh_project(False)
