    def closeEvent(self,event):
        if hasattr(self,'explorer') and self.explorer.pending:
            QMessageBox.information(self,'Explorer Running','Wait for Explorer loading to finish before closing.');event.ignore();return
        if hasattr(self,'explorer'):self.explorer.save()
        if self.project_pending or (self.project_worker and self.project_worker.isRunning()):
            QMessageBox.information(self,'Analysis Running','Wait for project analysis to finish before closing.');event.ignore();return
        if self.engine.active:
            answer=QMessageBox.question(self,'Stop Recording','Stop the current recording before closing?',QMessageBox.StandardButton.Yes|QMessageBox.StandardButton.Cancel,QMessageBox.StandardButton.Cancel)
            if answer!=QMessageBox.StandardButton.Yes or not self.stop():event.ignore();return
        if self.engine.pending_capture:
            answer=QMessageBox.question(self,'Unsaved Recording','Save this recording before closing? Discard permanently deletes this unsaved capture.',
                QMessageBox.StandardButton.Save|QMessageBox.StandardButton.Discard|QMessageBox.StandardButton.Cancel,QMessageBox.StandardButton.Cancel)
            if answer==QMessageBox.StandardButton.Save:
                if not self.save_trial_settings():event.ignore();return
            elif answer==QMessageBox.StandardButton.Discard:
                if not self.delete_pending_capture():event.ignore();return
            else:event.ignore();return
            if self.engine.pending_capture:event.ignore();return
        if hasattr(self,'view_session'):self.view_session.save()
        super().closeEvent(event)
        if event.isAccepted():
            self.explorer.reload_timer.stop();self.view_session.timer.stop();self.auto_stop_timer.stop();self.view_save_timer.stop();self.persist_view_choices()


